// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Türk ve dünya tiyatro edebiyatı: trajedi, komedi, dram ve çağdaş oyun yazarları (Sofokles, Shakespeare, Molière, İbsen, Çehov, Brecht, Haldun Taner) (orta).
const ozLiterature16Orta = <(String, String, List<String>, String)>[
  ('Poetika\'ya göre bütünüyle kötü olmayan soylu bir kahramanın ahlaki alçaklıktan değil de bilgisizlikten veya yanılgıdan kaynaklanan trajik hatasına ne denir?', 'Hamartia', ['Nemesis', 'Ekstasis', 'Dianoia'], 'Hamartia, okçulukta \'hedefi ıskalama\' kökünden gelir; Kral Oidipus\'un bilmeden babasını öldürmesi gibi trajik yanılgıyı ifade eder.'),
  ('Kral Oidipus\'ta Korinthos\'tan gelen habercinin kralı rahatlatmak isterken tam tersine onun gerçek kimliğini açığa çıkarıp bahtını tersine çevirmesi hangi dramatik ögedir?', 'Peripeteia (Baht dönüşü)', ['Prologos (Ön deyiş bölümü)', 'Stasimon (Duragan koro ezgisi)', 'Kommos (Karşılıklı ağıtlaşma)'], 'Peripeteia, eylemin beklentinin tam aksi yönüne kırılarak mutluluktan felakete ya da felaketten kurtuluşa ani dönüşmesidir.'),
  ('Bir trajedide kahramanın gizli bir akrabalığı, saklı kimliği veya ölümcül gerçeği birdenbire fark ederek bilgisizlikten bilgiye geçiş anını hangi terim karşılar?', 'Anagnorisis (Tanıma ve keşif)', ['Parodos (Koronun ilk girişi)', 'Eksodos (Oyunun kapanış sahnesi)', 'Stikhomythia (Tek dizelik atışma)'], 'Anagnorisis, karakterin kritik bir gerçeği veya başka bir kişinin gerçek kimliğini tanımasıdır; en etkili biçimi peripeteia ile eşzamanlı olanıdır.'),
  ('Trajedi oyuncularının boylarını heybetli göstermek ve sahnede tanrısal ya da soylu bir görkem yaratmak amacıyla giydikleri yüksek tabanlı çizmeler nasıl adlandırılır?', 'Kothurnos', ['Khimation', 'Peplos', 'Sokkos'], 'Kalın mantar veya ahşap tabanlı kothurnos çizmeleri trajedi aktörlerine boy kazandırırken, komedi oyuncuları alçak ve yumuşak pabuçlar (sokkos) giyerdi.'),
  ('Büyük Dionysia yarışmalarına katılan her trajedi şairinin üç trajediden oluşan üçlemesinin (trilogia) hemen ardından sergilemek zorunda olduğu alaycı ve neşeli dördüncü türe ne ad verilirdi?', 'Satir oyunu', ['Pantomim gösterisi', 'Mimos güldürüsü', 'Fescennini taşlaması'], 'Keçi ayaklı, at kuyruklu satirlerden oluşan korosuyla mitolojik konuları kaba ve neşeli dille işleyen satir oyunu, üç trajedinin yarattığı gerilimi dağıtırdı.'),
  ('Mitolojik efsaneler yerine yakın tarihsel bir olayı, Salamis Deniz Savaşı bozgununun Susa sarayındaki yankılarını konu edinen günümüze kalmış en eski Yunan trajedisi hangisidir?', 'Persler', ['Yalvarıcı Kızlar', 'Eumenidler', 'Trakhisli Kadınlar'], 'Aiskhylos\'un kendisinin de bizzat savaştığı Salamis Zaferi\'nden sekiz yıl sonra (MÖ 472) sahnelediği Persler, tarihsel konulu tek mevcut Yunan trajedisidir.'),
  ('Antik Yunan\'dan günümüze eksiksiz ulaşabilmiş tek trajedi üçlemesi olan ve kan davası geleneğinden bağımsız yargı düzenine geçişi simgeleyen Aiskhylos eseri hangisidir?', 'Oresteia', ['Danaidler', 'Lykurgeia', 'Oidipodeia'], 'Agamemnon, Adak Sunucular (Khoephoroi) ve Eumenidler oyunlarından oluşan Oresteia, kişisel öç zincirinin Atina Areopagos Mahkemesi ile sonlandırılışını işler.'),
  ('Oresteia üçlemesinin son halkası Eumenidler\'de, annesi Klytaimnestra\'yı öldüren Orestes\'i kovalayan öç tanrıçalarının (Erinyeler) yatıştırılarak iyicil koruyuculara dönüşmesini hangi tanrıça sağlar?', 'Athena', ['Artemis', 'Demeter', 'Aphrodite'], 'Bilgelik tanrıçası Athena, yurttaşlardan oluşan jüriyi kurup oyların eşit çıkması üzerine beraat oyu vererek Erinyeleri \'Eumenidler\'e (İyicil Tanrıçalar) dönüştürür.'),
  ('Oidipus\'un oğulları Eteokles ile Polyneikes\'in iktidar uğruna kentin yedi kapısı önünde birbirini boğazlamasını konu alan Aiskhylos trajedisi hangisidir?', 'Tebai\'ye Karşı Yediler', ['Yalvarıcı Kızlar', 'Fenikeli Kadınlar', 'Adak Sunucular'], 'MÖ 467 tarihli Tebai\'ye Karşı Yediler, Labdakos soyunun laneti altında iki kardeşin teke tek vuruşarak can vermesini destansı bir dille sahneler.'),
  ('Antigone\'de babası Kreon\'u tek adam inatçılığından vazgeçirmeye çalışan, sözünü dinletemeyince nişanlısının kapatıldığı taş mezarda canına kıyan genç prens kimdir?', 'Haimon', ['Teiresias', 'Polydoros', 'Neoptolemos'], 'Kreon\'un oğlu ve Antigone\'nin nişanlısı Haimon, babasına kent halkının sesine kulak vermesini öğütler; Antigone\'nin ölüsünü bulunca kendi kılıcıyla intihar eder.'),
  ('Kör ve sürgün Oidipus\'un kızı Antigone\'nin rehberliğinde Atina yakınlarındaki kutsal koruluğa sığınmasını ve Kral Theseus\'un himayesinde huzura kavuşmasını anlatan Sofokles oyunu hangisidir?', 'Oidipus Kolonos\'ta', ['Trakhisli Kadınlar', 'Herakles\'in Çocukları', 'İphigenia Aulis\'te'], 'Sofokles\'in doksanlı yaşlarında kendi doğduğu kasaba olan Kolonos\'u onurlandırarak yazdığı Oidipus Kolonos\'ta, ölümünden sonra torunu tarafından sahnelenmiştir.'),
  ('Tanrılığını yadsıyan kuzeni Kral Pentheus\'u cezalandırmak için Tebai kadınlarını vecd halinde dağlara çıkaran ve kralı öz annesi Agave\'ye parçalatan Dionysos\'un gazabını hangi Euripides oyunu işler?', 'Bakkhalar', ['Troyalı Kadınlar', 'Çılgın Herakles', 'Helena'], 'Euripides\'in Makedonya\'da ömrünün sonunda yazdığı Bakkhalar, akılcı baskı ile dizginlenemeyen irrasyonel doğa gücü arasındaki korkunç çatışmayı sergiler.'),
  ('Yalnızca av tanrıçası Artemis\'e bağlı kalarak aşktan uzak yaşayan iffetli üvey oğluna tutulan Kraliçe Phaidra\'nın yasak tutkusunu ve iftirasını konu alan Euripides trajedisi hangisidir?', 'Hippolytos', ['Alkestis', 'Andromakhe', 'Yalvarıcı Anneler'], 'Aphrodite\'yi küçümseyen Hippolytos\'tan tanrıçanın aldığı öcü işleyen bu eser, daha sonra Seneca ve Jean Racine\'in Phèdre trajedilerine kaynaklık etmiştir.'),
  ('Kocası Kral Admetos\'un ölümden kurtulabilmesi için hiç kimsenin yanaşmadığı fedakârlığı üstlenerek onun yerine yeraltı dünyasına inmeyi kabul eden eşin öyküsü hangi oyunda anlatılır?', 'Alkestis', ['İphigenia Aulis\'te', 'Hekabe', 'Elektra'], 'Euripides\'in bir dörtlemede satir oyunu yerine dördüncü sırada sahnelediği Alkestis, Herakles\'in Ölüm (Thanatos) ile güreşip kadını kurtarmasıyla mutlu sonla biter.'),
  ('Peloponnesos Savaşı sırasında Melos Adası halkının katledilmesine dolaylı bir protesto olarak yazılan, yıkılan kentin esir düşmüş kraliçesi ve kadınlarının çaresizliğini sergileyen savaş karşıtı oyun hangisidir?', 'Troyalı Kadınlar', ['Tebai\'ye Karşı Yediler', 'Persler', 'Fenikeli Kadınlar'], 'Euripides\'in MÖ 415\'te sahnelenen Troyalı Kadınlar eseri, zafer kazanmış görünen Yunanlıların vahşetini ve savaşın asıl kurbanlarının trajedisini gözler önüne serer.'),
  ('Yunan donanmasının Troya\'ya yelken açabilmesi uğruna rüzgâr bekleyen Başkomutan Agamemnon\'un, öz kızını Artemis sunağında kurban etmeye sürüklenişini anlatan Euripides eseri hangisidir?', 'İphigenia Aulis\'te', ['Orestes', 'Andromakhe', 'Herakles\'in Çocukları'], 'Agamemnon\'un Aхиlles ile evlilik bahanesiyle ordugâha getirttiği İphigenia\'nın gönüllü olarak ölüme yürüyüşünü işleyen oyun, şairin ölümünden sonra sahnelenmiştir.'),
  ('Borç batağındaki köylü Strepsiades\'in, haksız davaları bile laf cambazlığıyla kazanmayı öğrenmek için \'Düşünce Dükkânı\'na (Phrontisterion) gitmesini anlatarak Sokrates\'i sofist gibi hicveden komedya hangisidir?', 'Bulutlar', ['Kuşlar', 'Kurbağalar', 'Atlılar'], 'Aristofanes\'in Bulutlar (Nephelai) adlı oyunu, Sokrates\'i sepet içinde havada asılı duran bir doğa filozofu ve safsata hocası olarak karikatürize eder.'),
  ('Atinalıların mahkemelerde jüri üyeliği yapma ve herkesi yargılama saplantısını, babası Philokleon\'u eve kilitleyip köpeği peynir çaldığı için yargılatan oğul Bdelykleon üzerinden taşlayan Aristofanes oyunu hangisidir?', 'Eşekarıları', ['Barış', 'Kadınlar Savaşı', 'Plutos'], 'Eşekarıları (Sphekes), demagog Kleon\'un üç obolosluk jüri ücretiyle yurttaşları kendine bağımlı kılmasını ve Atina yargı sisteminin yozlaşmasını eleştirir.'),
  ('Büyük trajedi ustalarının ölümü üzerine Atina sahnesinin ıssız kaldığını düşünen tanrı Dionysos\'un, iyi bir şairi hayata döndürmek için yeraltı dünyasına (Hades) inişini ve Aiskhylos ile Euripides\'in dizelerini terazide tartmasını anlatan eser hangisidir?', 'Kurbağalar', ['Bulutlar', 'Eşekarıları', 'Şölen'], 'Aristofanes\'in Kurbağalar (Batrakhoi) oyunu, Batı edebiyatının ilk kapsamlı edebi eleştiri metinlerinden biri sayılır ve sonunda Dionysos Aiskhylos\'u seçer.'),
  ('Atina\'daki bitmek bilmeyen davalardan bıkan Peisetairos ve Euelpides adlı iki yurttaşın gökyüzü ile yeryüzü arasında \'Nephelokokkygia\' (Bulut-Guguk-Kuşu-Kenti) adlı ütopik bir devlet kurmasını anlatan oyun hangisidir?', 'Kuşlar', ['Atlılar', 'Plutos', 'Barış'], 'Aristofanes\'in en uzun ve en fantastik komedyası olan Kuşlar (Ornithes), gökyüzünde kurulan kent aracılığıyla tanrılara giden kurban dumanlarını kesip iktidarı ele geçirmeyi hicveder.'),
  ('Siyasal taşlamanın ve koro ağırlığının ortadan kalktığı, bunun yerine kentsoylu aile ilişkileri, yanlış anlamalar, genç âşıklar ve huysuz ihtiyarlar gibi karakter tiplerinin öne çıktığı Helenistik dönem Yunan Yeni Komedyası\'nın en büyük ustası kimdir?', 'Menandros', ['Kratinos', 'Theokritos', 'Arkhilokhos'], 'MÖ 4. yüzyıl sonlarında ürün veren Menandros, Yeni Komedya\'nın kurucu ustası olup Roma komedyası üzerinden tüm Avrupa töre ve karakter komedyasını etkilemiştir.'),
  ('Ocağının altında bulduğu altın dolu kabı çaldırma korkusuyla herkesten kuşkulanan yaşlı Euclio karakteri üzerinden Molière\'in ünlü Cimri oyununa doğrudan esin kaynağı olan Plautus eseri hangisidir?', 'Çömlek (Aulularia)', ['Urgan (Rudens)', 'Hortlak (Mostellaria)', 'Üç Akçe (Trinummus)'], 'Plautus\'un Aulularia (Çömlek) komedyasındaki Euclio tipi, Molière\'in Harpagon karakterinin ve altın kutusu sahnesinin doğrudan prototipidir.'),
  ('Çocukken birbirinden kopan aynı adlı iki kardeşin Epidamnus kentinde yol açtığı kimlik karışıklıklarını anlatan ve Shakespeare\'in Yanlışlıklar Komedyası\'na kaynaklık eden Plautus oyunu hangisidir?', 'İkizler (Menaechmi)', ['Esirler (Captivi)', 'Kartacalı (Poenulus)', 'İranlı (Persa)'], 'Plautus\'un Menaechmi adlı oyunu, Batı tiyatrosunda fiziksel benzerlikten doğan yanlış anlamalar (qui pro quo) komedisinin kurucu metnidir.'),
  ('Savaşta hiç yapmadığı kahramanlıklarla ve bütün kadınların kendisine hayran olduğu kuruntusuyla böbürlenen Pyrgopolynices adlı komik tipi edebiyata kazandıran Plautus yapıtı hangisidir?', 'Övüngen Asker (Miles Gloriosus)', ['Tecimen (Mercator)', 'Buğday Kurdu (Curculio)', 'Eşekler (Asinaria)'], 'Miles Gloriosus, sonradan İtalyan Commedia dell\'arte geleneğindeki Capitano ve Shakespeare\'deki Falstaff gibi palavra sıkan asker tiplerinin atası olmuştur.'),
  ('Kartaca kökenli eski bir köle olup Scipio çevresinin desteğiyle zarif, ölçülü bir Latince kullanan ve \'Ben insanım, insana dair hiçbir şeyi kendime yabancı saymam\' özdeyişini sahneye taşıyan Roma komedya yazarı kimdir?', 'Terentius', ['Catullus', 'Juvenalis', 'Martialis'], 'Publius Terentius Afer, kaba güldürüden kaçınıp ruhsal inceliğe ve eğitim sorunlarına odaklanmış; ünlü dizesi Kendini Cezalandıran (Heauton Timorumenos) oyununda geçmiştir.'),
  ('İmparatorluk dönemi Roma\'sında sahnelenmekten çok yüksek sesle okunmak (recitatio) için Stoacı felsefe, uzun retorik tiratlar ve kanlı şiddet motifleriyle trajediler yazan filozof-şair kimdir?', 'Lucius Annaeus Seneca', ['Marcus Tullius Cicero', 'Titus Lucretius Carus', 'Publius Ovidius Naso'], 'Seneca\'nın Medea, Thyestes, Phaedra gibi dokuz trajedisi; hayaletler, intikam tutkusu ve retorik görkemiyle Elizabeth Çağı İngiliz (Shakespeare) ve Fransız trajedisini derinden etkilemiştir.'),
  ('Piso kardeşlere yazdığı mektup biçimindeki Ars Poetica (Şiir Sanatı) adlı yapıtında bir oyunun beş perdeden oluşmasını, sahnede kanlı sahnelerin gösterilmemesini ve karakter tutarlılığını (decorum) öğütleyen Romalı şair kimdir?', 'Horatius', ['Vergilius', 'Propertius', 'Tibullus'], 'Horatius\'un Ars Poetica\'sı, Aristoteles\'in Poetika\'sı ile birlikte Rönesans ve Klasisizm kuramcılarının (özellikle Boileau\'nun) başucu kural kitabı olmuştur.'),
  ('Antik Yunan tiyatrosunda koronun orkestraya ilk kez yan geçitlerden girerken söylediği yürüyüş ezgisine ne ad verilir?', 'Parodos', ['Stasimon', 'Prologos', 'Kommos'], 'Prologostan sonra koronun orkestraya giriş müziği ve aynı zamanda o yan giriş koridorlarının mimari adı \'parodos\'tur.'),
  ('Başlangıçta oyuncuların giysilerini değiştirmesi için orkestra gerisine kurulan basit çadır veya kulübeyken zamanla görkemli taş sahne binasına dönüşen mimari bölüm hangisidir?', 'Skene', ['Diazoma', 'Koilon', 'Analemma'], 'Çadır anlamına gelen \'skene\', zamanla saray ya da tapınak cephesini simgeleyen kalıcı arka sahne yapısına dönüşmüş ve Batı dillerindeki \'scene\' sözcüğüne kaynaklık etmiştir.'),
  ('Antik Yunan ve Roma tiyatro mimarileri karşılaştırıldığında orkestra alanının kullanımına ilişkin hangi fark öne çıkar?', 'Roma\'da orkestra yarım daireye inip seçkin senatörlerin oturma yerine dönüşmüştür', ['Roma\'da orkestra iki kat büyütülerek gladyatör ve deniz savaşı havuzu yapılmıştır', 'Yunan tiyatrosunda orkestra yalnızca müzisyenlere ayrılırken Roma\'da koro dansına açılmıştır', 'Yunan tiyatrosunda orkestra çatıyla örtülüyken Roma\'da açık havaya çıkarılmıştır'], 'Roma tiyatrosunda koronun işlevi azaldığı için tam daire orkestra yarım daireye daraltılmış ve senatörlerin oturduğu protokol alanına çevrilmiştir.'),
  ('Aiskhylos\'un Agamemnon trajedisinde Troya\'dan savaş ganimeti olarak getirilen, Apollon\'un laneti yüzünden geleceği ve kendi ölümünü doğru bildiği halde kimseyi inandıramayan kahin prenses kimdir?', 'Kassandra', ['İsmene', 'Polyksena', 'Khrysothemis'], 'Priamos\'un kızı Kassandra, Agamemnon sarayının önündeyken içeride işlenecek çifte cinayeti ve Atreus hanedanının kanlı geçmişini görür ama koroyu zamanında ikna edemez.'),
  ('Aristoteles\'in Poetika\'sında bir trajediyi oluşturan altı temel öge (öykü/mythos, karakter/ethos, düşünce/dianoia, dil/leksis, ezgi/melos, görüntü/opsis) içinde \'trajedinin ruhu ve birincil ilkesi\' sayılan unsur hangisidir?', 'Mythos (Olay örgüsü)', ['Opsis (Sahne görselliği)', 'Ethos (Kahramanın mizacı)', 'Leksis (Şiirsel üslup)'], 'Aristoteles, trajedinin kişilerin değil eylemin ve yaşamın taklidi olduğunu belirterek olayların bütünlüklü kuruluşunu (mythos) en üst sıraya koyar.'),
  ('Eski Komedya\'da iki karşıt görüşü temsil eden kişilerin (örneğin Bulutlar\'da Haklı Söz ile Haksız Söz\'ün ya da Kurbağalar\'da Aiskhylos ile Euripides\'in) koro hakemliğinde yürüttüğü biçimsel tartışma sahnesine ne denir?', 'Agon', ['Eksodos', 'Monodia', 'Threnos'], 'Yunanca \'yarışma, mücadele\' anlamına gelen agon, Aristofanes komedyalarının omurgasını oluşturan simetrik yapılı fikir ve söz düellosudur.'),
  ('Atina Akropolisi\'nin güney yamacında yer alan ve Aiskhylos, Sofokles, Euripides ile Aristofanes\'in büyük yapıtlarının ilk kez seyirciyle buluştuğu en eski anıtsal tiyatro yapısı hangisidir?', 'Dionysos Eleuthereus Tiyatrosu', ['Efes Büyük Açıkhava Tiyatrosu', 'Aspendos Roma Tiyatrosu', 'Miletos Helenistik Tiyatrosu'], 'Akropolis\'in güney eteklerindeki Dionysos Tiyatrosu, MÖ 5. yüzyıl klasik Yunan dramasının dünya prömiyerlerine ev sahipliği yapmış kutsal merkezdir.'),
  ('Peloponnesos Yarımadası\'nda sağlık tanrısı Asklepios\'un kutsal alanında MÖ 4. yüzyılda mimar Genç Polykleitos tarafından tasarlanan ve kusursuz akustiğiyle günümüze en sağlam ulaşan Yunan tiyatrosu nerededir?', 'Epidauros', ['Korinthos', 'Olympos', 'Halikarnassos'], 'Epidauros Tiyatrosu, kireçtaşı oturma sıralarının düşük frekanslı uğultuları süzüp oyuncu sesini en üst sıraya bile net ileten akustik mühendisliğiyle ünlüdür.'),
  ('Aristoteles Poetika\'da trajediyi tarih yazımından ayırırken trajedi şiirinin tarihten \'daha felsefi ve daha derin\' olmasını hangi gerekçeye dayandırır?', 'Tarihin olmuş olan tekil olayları, şiirin ise olasılık veya zorunluluk gereği olabilecek tümeli anlatmasına', ['Tarihçilerin düzyazı kullanmasına karşılık şairlerin ölçülü ve müzikli vezinle yazmasına', 'Tarihin yalnızca kralların savaşlarını, trajedinin ise köylü ve zanaatkârların yaşamını işlemesine', 'Tarih metinlerinin kitaplıklarda kalmasına karşılık trajedilerin binlerce yurttaş önünde oynanmasına'], 'Aristoteles\'e göre tarih (örneğin Herodotos) tekili ve gerçekleşmiş olanı aktarır; şiir ve trajedi ise nedensellik (olasılık/zorunluluk) yasalarına göre evrenseli (tümeli) kurar.'),
  ('Kral Oidipus\'un sonunda felaketin tüm çıplaklığıyla ortaya çıkması üzerine annesi ve eşi İokaste kendini asarken, Oidipus\'un gözlerini İokaste\'nin altın broşlarıyla oyması hangi içsel hesaplaşmayı yansıtır?', 'Gözleri varken hakikate kör kaldığı ve ne yeraltında anne-babasına ne de dünyada çocuklarına bakacak yüzü olduğu düşüncesini', ['Apollon tapınağındaki rahiplerin vebayı durdurmak için kralın kör edilmesini şart koşmasını', 'Kayınbiraderi Kreon\'un kendisini idam ettirmesini önleyip acıma duygusu uyandırma isteğini', 'Kahin Teiresias\'ın kehanet gücünü ve bilicilik yetisini kör kalarak devralma arzusunu'], 'Oidipus bedensel gözleri açıkken gerçeği göremediğini (entelektüel körlük) kavrar ve Teiresias gibi dış dünyaya kapanarak içsel aydınlanmanın kefaretini öder.'),
  ('Yunan trajedisinde tek bir oyuncunun (çoğunlukla büyük bir acı veya coşku anındaki kadın kahramanın) koro eşliği olmadan tek başına söylediği lirik solo şarkıya hangi ad verilir?', 'Monodia', ['Parabasis', 'Prologos', 'Tetralogia'], 'Özellikle geç dönem Euripides trajedilerinde duygusal yoğunluğu artırmak için sıkça başvurulan bireysel solo ezgilere monodia (opera aryasının antik öncüsü) denir.'),
  ('Orta Çağ Avrupa tiyatrosunda İyilik, Ölüm, Zenginlik ve Bilgelik gibi soyut kavramların kişileştirilerek insan ruhunun kurtuluş mücadelesini sahnelediği alegorik oyun türüne ne ad verilir?', 'Moralite (Ahlak oyunu)', ['Mister (İncil çevrimi oyunu)', 'Mirakl (Aziz mucizesi oyunu)', 'Pastoral (Çoban aşkı eglogu)'], '15. yüzyılda yaygınlaşan moralite oyunları (en ünlüsü İngiliz edebiyatındaki Everyman), erdem ve günahları kişileştirerek Hristiyan ahlak dersi verir.'),
  ('İspanyol Altın Çağı tiyatrosunda zorba komutan Fernán Gómez\'i elbirliğiyle öldüren köylülerin, işkence altında bile \'Onu kim öldürdü?\' sorusuna tek ağızdan köylerinin adını haykırdığı Lope de Vega oyunu hangisidir?', 'Fuenteovejuna (Koyun Pınarı)', ['Peribáñez ve Ocaña Komutanı', 'Bahçıvanın Köpeği (El perro del hortelano)', 'Zalamea Kadısı (El alcalde de Zalamea)'], 'Lope de Vega\'nın 1619\'da yayımlanan Fuenteovejuna eseri, bireysel kahraman yerine bütün bir köy halkını kolektif başkahraman yapan ortak direniş klasiğidir.'),
  ('Yıldız falında zalim bir tiran olacağı görülünce babası Kral Basilio tarafından doğduğundan beri ıssız bir kuleye zincirlenen Polonya Prensi Segismundo\'nun özgür irade ve yanılsama sınavını işleyen Calderón de la Barca başyapıtı hangisidir?', 'Hayat Bir Rüyadır', ['Kendi Şerefinin Hekimi', 'Büyük Dünya Tiyatrosu', 'Görünmez Sevgili'], 'Pedro Calderón de la Barca\'nın 1635 tarihli La vida es sueño (Hayat Bir Rüyadır) oyunu, İspanyol Barok tiyatrosunun en derin felsefi dramıdır.'),
  ('Shakespeare\'den hemen önce İngiliz Rönesans sahnesine uyaksız beşli ölçü olan \'blank verse\'ün görkemini kazandıran ve sınırsız bilgi-güç uğruna ruhunu Mephistopheles aracılığıyla Lucifer\'e satan Doktor Faustus trajedisini yazan şair kimdir?', 'Christopher Marlowe', ['Thomas Kyd', 'John Webster', 'Edmund Spenser'], 'Genç yaşta bir han kavgasında öldürülen Christopher Marlowe; Doktor Faustus, Büyük Timur ve Maltalı Yahudi oyunlarıyla Elizabeth dönemi trajedisinin kapısını açmıştır.'),
  ('Shakespeare\'in Venedik Taciri oyununda arkadaşı Bassanio\'ya kefil olan Antonio\'dan vadesinde ödenmeyen üç bin duka altın karşılığında sözleşme gereği \'kalbine yakın bir libre et\' kesmek isteyen tefeci kimdir?', 'Shylock', ['Malvolio', 'Prospero', 'Polonius'], 'Yahudi tefeci Shylock\'un mahkemedeki talebi, genç yargıç Balthazar kılığına giren zeki Portia\'nın \'et kesebilirsin ama sözleşmede bir damla bile kan dökmek yazmıyor\' savunmasıyla bozulur.'),
  ('Atina yakınlarındaki büyülü ormanda Peri Kralı Oberon\'un soytarısı Puck\'ın göz kapaklarına damlattığı aşk çiçeği özsuyu yüzünden Kraliçe Titania\'nın eşek başlı dokumacı Bottom\'a âşık olmasını konu alan Shakespeare komedyası hangisidir?', 'Bir Yaz Gecesi Rüyası', ['On İkinci Gece', 'Nasıl Hoşunuza Giderse', 'Kış Masalı'], 'Bir Yaz Gecesi Rüyası; saray düğünü, ormanda kaçan dört genç âşık, periler dünyası ve esnaf tiyatrocuların (Pyramus ile Thisbe oyunu) iç içe geçtiği büyülü bir komedyadır.'),
  ('Kardeşi Antonio\'nun ihanetiyle Milano Düklüğü\'nden sürülüp kızı Miranda ile ıssız bir adaya yerleşen, hava ruhu Ariel ve yabanıl köle Caliban\'a hükmederek düşmanlarını deniz kazasıyla adaya çeken büyücü dük hangi oyunun başkahramanıdır?', 'Fırtına (The Tempest)', ['Kısasa Kısas (Measure for Measure)', 'Hırçın Kız (The Taming of the Shrew)', 'Kuru Gürültü (Much Ado About Nothing)'], 'Shakespeare\'in tek başına yazdığı son eseri kabul edilen Fırtına\'da Prospero\'nun sonunda büyü asasını kırıp kitaplarını denize gömmesi, yazarın sahneye vedası olarak yorumlanır.'),
  ('Klasik Yunan trajedisi ile Shakespeare trajedisi biçimsel kurallar açısından karşılaştırıldığında Shakespeare\'in estetiğini hangi özellik belirler?', 'Zaman ve mekân birliğini reddedip kanlı olayları, soylularla halkı ve trajik olanla komik ögeleri aynı sahnede kaynaştırması', ['Aristoteles\'in yirmi dört saat sınırına ve tek mekân ilkesine Fransız şairlerinden daha sıkı biçimde bağlanması', 'Her perdenin sonunda on beş kişilik yurttaş korosuna ahlaki değerlendirme şarkıları söyletmesi', 'Sahneye hiçbir doğaüstü varlık, cadı ya da hayalet çıkarmayarak katı pozitivist gerçekçilik uygulaması'], 'Elizabeth çağı tiyatrosu ve Shakespeare; üç birlik kuralına uymaz, yıllara yayılan olayları farklı ülkelerde gezdirir ve Kral Lear\'daki Soytarı ya da Macbeth\'teki Kapıcı gibi komik sahneleri trajediye katar.'),
  ('17. yüzyıl Fransız Klasisizmi\'nin estetik yasalarını 1674\'te yayımladığı Şiir Sanatı (L\'Art poétique) adlı manzum yapıtında sistemleştiren, akıl ve sağduyuyu (bon sens) yücelten kuramcı kimdir?', 'Nicolas Boileau', ['François de Malherbe', 'Jean de La Bruyère', 'Charles Perrault'], 'Boileau, Şiir Sanatı\'nda \'Bir tek yerde, bir tek günde tamamlanan tek bir olgu sahneyi sonuna dek dolu tutsun\' dizeleriyle üç birlik kuralını kesin yasaya dönüştürmüştür.'),
  ('Babasının onurunu kurtarmak için sevgilisi Chimène\'in babasını düelloda öldürmek zorunda kalan Don Rodrigue\'in \'aşk ile ödev/onur\' çatışmasını işleyen ve 1637\'de Fransız Akademisi\'nde büyük kurallar tartışması koparan trajikomedi hangisidir?', 'Le Cid', ['Cinna', 'Britannicus', 'Bérénice'], 'Pierre Corneille\'in Le Cid adlı oyunu büyük halk başarısı kazanmasına rağmen üç birlik ve \'inandırıcılık/uygunluk\' (bienséance) kurallarını esnettiği gerekçesiyle Kardinal Richelieu yönetimindeki Akademi\'de tartışılmıştır.'),
  ('Jean Racine\'in 1677 tarihli en olgun başyapıtı kabul edilen, Kral Thésée\'nin öldüğü söylentisi üzerine üvey oğluna duyduğu günahkâr aşkı itiraf edip reddedilince vicdan azabı ve zehirle can veren kraliçenin trajedisi hangisidir?', 'Phèdre', ['Esther', 'Athalie', 'Bajazet'], 'Euripides ve Seneca\'nın Hippolytos metinlerinden beslenen Racine\'in Phèdre\'i, on iki heceli aleksandren dizelerin müziğiyle yasak tutkunun ve suçluluk bilincinin zirvesidir.'),
  ('Toplumun dalkavukluk ve yalan üzerine kurulu nezaket kurallarına savaş açan dürüst ama hırçın Alceste\'in, tam zıddı olan sosyete kelebeği ve dedikoducu Célimène\'e tutkuyla bağlanışını işleyen en ciddi Molière komedyası hangisidir?', 'Adamcıl (Le Misanthrope)', ['Kadınlar Mektebi (L\'École des femmes)', 'Zoraki Hekim (Le Médecin malgré lui)', 'Sicilyalı (Le Sicilien)'], 'Molière\'in manzum başyapıtlarından Adamcıl (1666), gülmece ile hüznü iç içe geçirerek mutlak dürüstlük talebinin uzlaşmacı salon toplumundaki yalnızlığını irdeler.'),
  ('Aldatılma korkusuyla dört yaşından itibaren manastırda dış dünyadan habersiz ve cahil büyüttüğü Agnès\'le evlenmeyi planlayan yaşlı Arnolphe\'un, genç aşkın doğal uyanışı karşısında bozguna uğradığı Molière oyunu hangisidir?', 'Kadınlar Mektebi', ['Gülünç Kibarlar', 'Kibarlık Budalası', 'Cimri'], '1662 tarihli Kadınlar Mektebi (L\'École des femmes), kadını cehaletle zapt etme zihniyetini yıkan ilk büyük modern Fransız karakter komedyası sayılır.'),
  ('18. yüzyıl İtalya\'sında Commedia dell\'arte\'nin yozlaşmış maskelerini ve doğaçlama kalıplarını kaldırıp yerine tam yazılı metne ve gerçekçi orta sınıf karakterlerine dayalı komedya reformunu getiren Venedikli yazar kimdir?', 'Carlo Goldoni', ['Vittorio Alfieri', 'Pietro Metastasio', 'Ludovico Ariosto'], 'İtalyan Molière\'i diye anılan Carlo Goldoni, maskeli doğaçlama tiyatrosunu aşamalı olarak dönüştürerek 150\'yi aşkın yazılı karakter ve töre komedyası üretmiştir.'),
  ('Floransa\'da işlettiği otele gelen markiyi ve kontu parmağında oynattıktan sonra kadın düşmanı şövalye Ripafratta\'yı da kendine sırılsıklam âşık edip sonunda kendi uşağı Fabrizio ile evlenen zeki ve bağımsız kadını hangi Goldoni oyunu anlatır?', 'Otelci Kadın', ['Chioggia Kavgaları', 'Yeni Ev', 'Yalancı'], '1753 tarihli La Locandiera (Otelci Kadın), aristokratların kibrini alt eden emekçi ve özgüvenli kadın karakter Mirandolina ile Aydınlanma ruhunu sahneye taşır.'),
  ('Fransız Devrimi arifesinde Kont Almaviva\'nın karşısına dikilen zeki uşak karakterinin \'Soylu doğmak için dünyaya gelme zahmetinden başka ne yaptınız?\' tiradıyla aristokrasiyi sarsan Figaro\'nun Düğünü ve Sevilla Berberi\'nin yazarı kimdir?', 'Pierre-Augustin Caron de Beaumarchais', ['Denis Diderot', 'Pierre de Marivaux', 'Alain-René Lesage'], 'Beaumarchais\'nin Sevilla Berberi (Rossini operası) ve Kral XVI. Louis\'nin uzun süre yasakladığı Figaro\'nun Düğünü (Mozart operası), üçüncü sınıfın devrimci özgüvenini müjdeler.'),
  ('Hamburg Dramaturgisi adlı kuramsal eseriyle Alman tiyatrosunu Fransız Klasisizmi\'nin katı taklitçiliğinden kurtarıp Shakespeare\'e yönelten ve Haçlılar çağında Kudüs\'te üç semavi dinin kardeşliğini \'Üç Yüzük Meseli\' ile savunan Bilge Nathan\'ı yazan Aydınlanma düşünürü kimdir?', 'Gotthold Ephraim Lessing', ['Johann Christoph Gottsched', 'Friedrich Gottlieb Klopstock', 'Christoph Martin Wieland'], 'Lessing; Minna von Barnhelm ile ilk büyük Alman komedyasını, Miss Sara Sampson ve Emilia Galotti ile burjuva trajedisini, Bilge Nathan ile de hoşgörü felsefesini kurmuştur.'),
  ('18. yüzyılın son çeyreğinde Almanya\'da katı Aydınlanma akılcılığına ve Fransız kurallarına başkaldırarak tutkuyu, bireysel deha kavramını ve özgürlük isyanını sahneye taşıyan gençlik hareketinin adı (Friedrich Maximilian Klinger\'in bir oyunundan alınarak) nedir?', 'Sturm und Drang (Fırtına ve Coşku)', ['Neue Sachlichkeit (Yeni Nesnellik)', 'Biedermeier (Evcil Dinginlik)', 'Fin de Siècle (Yüzyıl Sonu)'], 'Genç Goethe ve genç Schiller\'in de ilk oyunlarını verdiği Sturm und Drang akımı, Alman Romantizminin önünü açan coşkulu edebi başkaldırıdır.'),
  ('Kardeşi Franz\'ın entrikaları yüzünden babası tarafından evlatlıktan reddedildiğini sanarak Bohemya ormanlarında eşkıya çetesi kuran ve adaletsiz düzene başkaldıran Karl Moor\'un trajedisini 22 yaşında yazan Alman şair ve eseri hangisidir?', 'Friedrich Schiller – Haydutlar', ['Heinrich von Kleist – Homburg Prensi', 'Georg Büchner – Danton\'un Ölümü', 'Johann Wolfgang von Goethe – Egmont'], 'Schiller\'in 1782\'de Mannheim\'da sahnelendiğinde salonu ayağa kaldıran ilk oyunu Haydutlar (Die Räuber), Sturm und Drang akımının simge yapıtıdır.'),
  ('Goethe\'nin Faust eserinin Birinci Bölümü\'nde gençleştirilen Faust\'un aşkla bağlandığı, ancak annesinin uyku ilacıyla ölümü, ağabeyinin düelloda vurulması ve evlilik dışı bebeğini boğması üzerine zindana düşen masum genç kız kimdir?', 'Gretchen', ['Spartalı Helena', 'Prenses Leonore', 'Çingene Mignon'], 'Faust I\'in duygusal omurgasını oluşturan Gretchen trajedisinde genç kız, Mephistopheles\'in atlarıyla zindandan kaçmayı reddedip ilahi yargıya sığınarak kurtuluşa (\'Kurtuldu!\') erer.'),
  ('25 Şubat 1830 gecesi Paris\'te Comédie-Française sahnesinde kırmızı yelekli genç romantiklerle perukalı klasisizm yanlıları arasında yumruklu kavgalara sahne olan ve Romantizmin Klasisizme karşı kesin zaferini ilan eden Victor Hugo oyunu hangisidir?', 'Hernani', ['Marion de Lorme', 'Lucrezia Borgia', 'Angelo'], 'Tiyatro tarihine \'Hernani Savaşı\' (Bataille d\'Hernani) olarak geçen bu prömiyerde Hugo, klasik aleksandren dize kalıbını ve sahne kurallarını kırarak romantik dramı resmî sahneye kabul ettirmiştir.'),
  ('Yirmi üç yaşında ölen Alman yazar Georg Büchner\'in 1836\'da taslak halinde bıraktığı, yüzbaşısını tıraş edip doktorun bezelye diyeti deneyinde kobay olarak kullanılan yoksul bir erin sevgilisi Marie\'yi bıçaklamasını anlatarak modern dışavurumcu ve epik tiyatroya öncülük eden oyunu hangisidir?', 'Woyzeck', ['Leonce ile Lena', 'Danton\'un Ölümü', 'Maria Magdalena'], 'Büchner\'in gerçek bir adli vakadan yola çıkarak kopuk kısa sahnelerle yazdığı Woyzeck, dünya tiyatrosunda alt sınıftan ezilen sıradan bir proleteri trajik başkahraman yapan ilk modern oyundur.'),
  ('Shakespeare\'in On İkinci Gece (Twelfth Night) komedyasında deniz kazasından kurtulduktan sonra İlirya topraklarında erkek kılığına girerek \'Cesario\' adını alan ve Dük Orsino ile Kontes Olivia arasında aşk üçgeni doğuran genç kız kimdir?', 'Viola', ['Katharina', 'Beatrice', 'Rosalind'], 'On İkinci Gece\'de Viola erkek uşak Cesario kılığında hizmet ettiği Dük Orsino\'ya âşık olur; Dük\'ün kur yapmaya gönderdiği Olivia ise Cesario\'ya tutulur; düğüm ikiz kardeş Sebastian\'ın gelişiyle çözülür.'),
  ('Shakespeare\'in Roma tarihinden uyarladığı Julius Caesar trajedisinde, Sezar\'ı kişisel kinden değil Roma cumhuriyetini tek adam tiranlığından koruma idealiyle hançerleyen ve Antonius\'un bile ölüsü başında \'Onların içinde en soylu Romalı buydu\' dediği karakter kimdir?', 'Marcus Brutus', ['Gaius Cassius', 'Marcus Lepidus', 'Octavius Caesar'], 'Julius Caesar oyununun gerçek içsel ve ahlaki trajik kahramanı, dost sevgisi ile cumhuriyetçi yurttaşlık ödevi arasında parçalanan idealist Brutus\'tur.'),
  ('Molière\'in taşradan Paris\'e yeni gelmiş iki özentili genç kızın (Madelon ile Cathos) kendilerini reddeden taliplerinin uşaklarını \'Marki de Mascarille\' sanarak hayran kalmasını alaya aldığı tek perdelik ilk büyük Paris başarısı hangisidir?', 'Gülünç Kibarlar', ['Bilgiç Kadınlar', 'Kocalar Mektebi', 'George Dandin'], '1659 tarihli Gülünç Kibarlar (Les Précieuses ridicules), dönemin Paris salonlarındaki yapmacık ve ağdalı konuşma modasını (préciosité) keskin bir hicivle yıkmıştır.'),
  ('Molière\'in Scapin\'in Dolapları komedyasında kurnaz uşak Scapin\'in cimri baba Géronte\'tan oğlunun fidyesi için beş yüz altın koparmak üzere uydurduğu ve Fransızcada deyimleşen (\'O kahrolası kadırgada ne işi vardı!\') yalan nedir?', 'Genç beyin limanda gezerken bir Türk kadırgasına davet edilip denize açılarak esir alındığı yalanı', ['Genç beyin Venedik karnavalında dükün yeğeniyle düello yapıp zindana atıldığı yalanı', 'Korsanların konağın mahzenine tünel kazıp tüm çeyiz sandıklarını gemiye yüklediği yalanı', 'Genç beyin simya deneyi sırasında komşu konağın çatısını havaya uçurduğu yalanı'], 'Scapin\'in uydurduğu Türk kadırgası öyküsü karşısında cimri Géronte\'un parayı vermemek için çırpınarak sürekli \'Mais que diable allait-il faire dans cette galère?\' demesi dünya tiyatrosunun en komik repliklerindendir.'),
  ('Shakespeare\'in III. Richard adlı tarihsel trajedisinde doğuştan kambur olan Gloucester Dükü Richard\'ın tahta geçmek için öz ağabeyi Clarence ve Londra Kulesi\'ndeki iki küçük yeğeni dahil herkesi ortadan kaldırdıktan sonra Bosworth Meydan Savaşı\'nda haykırdığı ünlü son çığlık nedir?', 'Bir at! Bir at! Krallığıma karşılık bir at!', ['Sen de mi ihanete katıldın evladım!', 'Geri kalan her şey yalnızca sessizliktir!', 'Söndü, söndü kısacık mum, hayat yürüyen bir gölgedir!'], 'Savaş alanında atı öldürülen III. Richard\'ın \'A horse! a horse! my kingdom for a horse!\' çığlığı, uğruna sayısız cinayet işlediği tacın ölüm anında tek bir at kadar bile değeri kalmadığını gösteren çarpıcı ironidir.'),
  ('İngiltere\'de Oliver Cromwell önderliğindeki Püriten Parlamento yönetiminin tiyatroları \'ahlaksızlık yuvası\' sayarak on sekiz yıl boyunca (1642-1660) kapatmasının ardından II. Charles\'ın tahta dönüşüyle başlayan Restorasyon Tiyatrosu\'nun İngiliz sahnesine getirdiği en köklü yenilik nedir?', 'Kadın rollerinin genç erkek çocuklar yerine ilk kez resmî olarak profesyonel kadın aktrisler tarafından canlandırılması', ['Üstü kapalı salonların yıkılarak yalnızca gündüz ışığında açık hava avlularında oyun sergilenmesi', 'Komedi türünün saray fermanıyla yasaklanarak yalnızca İncil konulu dinsel trajedilere izin verilmesi', 'Sahne önündeki perde ve boyalı dekor kullanımının kaldırılıp tamamen çıplak platforma dönülmesi'], 'Elizabeth ve Shakespeare döneminde Juliet veya Lady Macbeth dahil tüm kadın rollerini sesleri kalınlaşmamış oğlan çocukları oynarken, 1660 Restorasyon fermanıyla İngiliz sahnesine ilk kez kadın oyuncular çıkmıştır.'),
  ('Jean Racine\'in Troya Savaşı sonrası Epir Kralı Pyrrhus\'un esiri Andromaque\'a, Yunan elçisi Oreste\'in Hermione\'ye, Hermione\'nin ise Pyrrhus\'a karşılıksız tutulduğu ölümcül aşk zincirini işleyen 1667 tarihli ilk büyük zaferi hangisidir?', 'Andromaque', ['Bérénice', 'Iphigénie', 'Mithridate'], 'Racine\'in Andromaque trajedisi (\'O beni sevmiyor, ben onu seviyorum\' zinciri), klasik Fransız sahnesinde yaşlı Corneille\'in egemenliğini sarsıp Racine çağını başlatmıştır.'),
  ('Fransa\'da Kral XIV. Louis\'nin 1680 tarihli fermanıyla Molière\'in eski topluluğu ile Hôtel de Bourgogne oyuncularının birleştirilmesi sonucu kurulan ve \'Molière\'in Evi\' diye de anılan en köklü ulusal devlet tiyatrosu hangisidir?', 'Comédie-Française', ['Théâtre Libre', 'Vieux-Colombier', 'Odéon Tiyatrosu'], '1680\'den beri kesintisiz faaliyet gösteren Comédie-Française, dünyanın en eski kurumsal ulusal tiyatrosu olup Molière\'in Hastalık Hastası\'nda üzerinde can verdiği koltuğu hâlâ korur.'),
  ('Schiller\'in iki rakip kraliçeyi, İngiltere Kraliçesi I. Elizabeth ile tutsak İskoçya Kraliçesi\'ni gerçekte hiç buluşmadıkları halde Fotheringhay Şatosu bahçesinde kurgusal bir yüzleşme sahnesinde karşı karşıya getirdiği tarihsel trajedisi hangisidir?', 'Maria Stuart', ['Messinalı Gelin', 'Cenova\'da Fiesco\'nun İhaneti', 'Don Carlos'], 'Schiller\'in 1800 tarihli simetrik yapılı başyapıtı Maria Stuart, tarihsel gerçekliği dramatik hakikat uğruna dönüştürerek tutsak kraliçenin ahlaki zaferini ve özgürlüğünü işler.'),
  ('Shakespeare\'in Kuru Gürültü (Much Ado About Nothing) komedyasında başlangıçta aşkla ve evlilikle alay edip sürekli hazırcevap laf düellosuna tutuşan, dostlarının bahçede kasıtlı duyurduğu dedikodularla birbirlerine âşık olduklarını kabul eden ünlü çift kimdir?', 'Beatrice ile Benedick', ['Hermia ile Lysander', 'Celia ile Oliver', 'Bianca ile Lucentio'], 'Kuru Gürültü\'de Hero ve Claudio\'nun geleneksel romantik öyküsünün yanında, Beatrice ile Benedick\'in \'neşeli söz savaşı\' romantik komedideki \'nefret ederken âşık olan zeki çift\' arketipini yaratmıştır.'),
  ('Molière\'in Don Juan ya da Taştan Şölen adlı beş perdelik düzyazı oyununda, din ve ahlak yasalarıyla alay eden efendisinin yanında korkak ama sağduyulu halk vicdanını temsil eden sadık uşağı kimdir?', 'Sganarelle', ['Mascarille', 'Covielle', 'Sosie'], 'Molière\'in pek çok oyununda bizzat canlandırdığı Sganarelle karakteri, Don Juan\'da efendisinin felsefi inkârcılığı karşısında şaşkın kalan ve oyun sonunda \'Benim aylıklarım ne olacak!\' diye bağıran unutulmaz uşaktır.'),
  ('Klasisizm döneminde Fransız trajedi şairlerinin (Corneille, Racine) neredeyse zorunlu olarak kullandıkları, altıncı heceden sonra durak (césure) içeren on iki heceli uyaklı dize biçimine ne ad verilir?', 'Aleksandren', ['Terza rima', 'Pentametre', 'Sonnet sarmalı'], 'Adını Orta Çağ\'daki Büyük İskender (Roman d\'Alexandre) şiirinden alan 12 heceli (6+6 duraklı) aleksandren dizesi, Fransız klasik trajedisinin ve manzum komedyasının temel ölçüsüdür.'),
  ('Klasik Fransız trajedisinde \'bienséance\' (edeplilik ve yakışık alır olma) ile \'vraisemblance\' (akla ve gerçeğe benzerlik) ilkelerinin sahne pratiğindeki en doğrudan sonucu hangisidir?', 'Düello, intihar ve savaş gibi fiziksel şiddet olaylarının sahne arkasında gerçekleşip bir haberci veya sırdaş anlatımıyla bildirilmesi', ['Kral ve kraliçelerin mutfakta yemek pişirirken ya da sokakta alışveriş yaparken doğal halleriyle gösterilmesi', 'Seyircinin sıkılmaması için her perdenin arasına ip cambazları ve palyaço danslarının yerleştirilmesi', 'Tarihsel gerçekliğe sadık kalmak adına sahnede gerçek atların ve top atışlarının kullanılması'], 'Bienséance kuralı, seyircinin estetik ve ahlaki zevkini incitmemek için kan dökülmesini ve kaba bedensel eylemleri sahne dışına iter; bu da \'sırdaş\' (confident) ve \'anlatı\' (récit) sahnelerini doğurmuştur.'),
  ('Alman Romantiklerinin ve Gotthold Ephraim Lessing\'in Fransız Klasisizmine karşı Shakespeare\'i bayraklaştırmalarının temel estetik nedeni nedir?', 'Shakespeare\'in mekanik dış kurallar yerine doğanın kendi organik bütünlüğünü ve insan ruhunun tüm çelişkilerini yansıttığını düşünmeleri', ['Shakespeare\'in tüm oyunlarını katı Protestan ilahileri ve Latince kilise duaları biçiminde kurgulamış olması', 'Shakespeare\'in üç birlik kuralını Boileau ve Racine\'den çok daha tavizsiz biçimde uygulamış olması', 'Shakespeare oyunlarında hiç kral veya soylu karaktere yer verilmeyip yalnızca fabrika işçilerinin anlatılması'], 'Lessing (17. Edebiyat Mektubu ve Hamburg Dramaturgisi), Herder ve Goethe; Fransız trajedisini yapay ve soğuk bulurken Shakespeare\'i Antik Yunan ruhuna gerçek anlamda en yakın doğal deha saymışlardır.'),
  ('Pierre de Marivaux\'nun 1730 tarihli Aşk ve Rastlantının Oyunu (Le Jeu de l\'amour et du hasard) adlı zarif komedyasında, görücü usulü evlenecekleri kişiyi gizlice tartmak için birbirlerinden habersiz aynı hileye başvuran Silvia ve Dorante ne yapar?', 'Her ikisi de kendi hizmetçileriyle kılık ve kimlik değiştirerek uşak-oda hizmetçisi görünümünde birbirlerine âşık olurlar', ['Her ikisi de yüzlerine Venedik karnaval maskesi takıp kendilerini seksen yaşında dul akrabalar gibi tanıtırlar', 'İkiz kardeşlerini kendi yerlerine görüşmeye gönderip perde arkasından konuşmaları not alırlar', 'Birbirlerine sahte iflas mektupları yollayarak karşı tarafın servet avcısı olup olmadığını denerler'], 'Fransızcada zarif ve incelikli aşk-söz oyunlarına \'marivaudage\' terimini kazandıran Marivaux\'nun bu en ünlü eserinde, efendiler hizmetçi kılığında, hizmetçiler de efendi kılığında birbirlerine tutulur.'),
  ('Georg Büchner\'in 1835 tarihli ilk oyunu Danton\'un Ölümü, Fransız Devrimi\'nin Terör Dönemi\'nde hangi iki devrimci liderin ve tarih anlayışının giyotin gölgesindeki çarpışmasını sahneye taşır?', 'Yaşam sevincini ve terörün durmasını isteyen Danton ile soğuk erdem ve devrimci şiddeti savunan Robespierre', ['Kral XVI. Louis\'yi kaçırmak isteyen Mirabeau ile jakoben gazeteci Marat\'yı bıçaklayan Charlotte Corday', 'Cumhuriyeti yıkmaya hazırlanan Napolyon Bonapart ile sürgündeki aristokrat lider Vikont Chateaubriand', 'Paris Komünü barikatlarını kuran Blanqui ile geçici hükümet başkanı Adolphe Thiers'], 'Büchner, gerçek meclis tutanaklarını kullanarak yazdığı Danton\'un Ölümü\'nde \'devrimin kendi çocuklarını Satürn gibi yuttuğu\' tarihsel yazgıcılığı Danton ve Robespierre karşıtlığıyla çözümler.'),
  ('Friedrich Schiller\'in İspanya Kralı II. Felipe\'nin baskıcı engizisyon rejimine karşı Flandre (Hollanda) halkına düşünce özgürlüğü talep eden Posa Markisi\'nin \'Efendimiz, düşünce özgürlüğü veriniz!\' çığlığıyla ünlü dramı hangisidir?', 'Don Carlos', ['Haydutlar', 'Wilhelm Tell', 'Wallenstein\'ın Karargâhı'], 'Schiller\'in Sturm und Drang coşkusundan Weimar Klasisizminin olgun ölçülü diline geçişini simgeleyen Don Carlos (1787), Posa Markisi aracılığıyla Aydınlanma\'nın insan hakları idealini haykırır.'),
  ('Shakespeare\'in Romeo ve Juliet trajedisinde ne Montague ne de Capulet ailesinden olduğu halde sokak düellosunda Romeo\'nun kolları arasında can verirken her iki aileyi de \'İkinizin de ocağına veba kıran girsin!\' sözüyle lanetleyen nüktedan dost kimdir?', 'Mercutio', ['Benvolio', 'Kont Paris', 'Tybalt'], '\'Kraliçe Mab\' tiradıyla da ünlü Mercutio\'nun Tybalt\'ın kılıcıyla ölümü, oyunun neşeli ve şiirsel ilk yarısından geri dönülmez kanlı trajediye kırıldığı dönüm noktasıdır.'),
  ('Shakespeare\'in Bir Yaz Gecesi Rüyası komedyasının son perdesinde Atina esnafının (dokumacı Bottom, marangoz Quince ve arkadaşlarının) Dük Theseus\'un düğününde son derece acemice ve gülünç biçimde oynadıkları antik aşk trajedisi hangisidir?', 'Pyramus ile Thisbe', ['Orpheus ile Eurydike', 'Hero ile Leandros', 'Dido ile Aeneas'], 'Ovidius\'un Dönüşümler\'indeki duvar çatlağından konuşan Babil\'li âşıklar Pyramus ile Thisbe\'nin trajik öyküsü (ki Romeo ve Juliet\'in de özüdür), esnafın elinde duvar ve aslan rolleriyle unutulmaz bir komediye dönüşür.'),
  ('Alman tiyatrosunda Otuz Yıl Savaşları\'nın ünlü başkomutanının imparatora ihaneti ve yıldızlara duyduğu kaderci güveni Wallenstein\'ın Karargâhı, Piccolominiler ve Wallenstein\'ın Ölümü adlı dev üçlemeyle sahneleyen şair kimdir?', 'Friedrich Schiller', ['Gotthold Ephraim Lessing', 'Heinrich Heine', 'Friedrich Hebbel'], 'Schiller\'in 1799\'da tamamladığı Wallenstein üçlemesi, Alman dilinde yazılmış en kapsamlı ve derinlikli tarihsel-politik trajedi dizisi kabul edilir.'),
  ('Klasik komedyada Molière\'in yarattığı uşak ve hizmetçi tiplerinin (Toinette, Dorine, Scapin) dramatik yapıdaki ortak işlevi nedir?', 'Efendilerinin saplantılarını ve budalalıklarını keskin halk sağduyusuyla teşhir edip genç âşıkların kavuşmasına zekâlarıyla aracılık etmek', ['Efendilerinin servetini çalarak oyun sonunda konağın yeni sahibi olup soylu unvanı satın almak', 'Ahlaki düzeni bozan kötücül entrikalar kurup oyun sonunda kralın muhafızlarınca zindana atılmak', 'Koro şefi gibi her perdenin başında sahne önüne çıkıp Latince felsefi özdeyişler okumak'], 'Tartuffe\'teki Dorine veya Hastalık Hastası\'ndaki Toinette gibi hizmetçiler, saplantıyla körleşmiş burjuva aile babalarının karşısında cesur, pratik ve sağlıklı aklın sesidir.'),
  ('Shakespeare\'in Antonius ve Kleopatra trajedisinde Roma üçlü yönetiminin doğu komutanı Marcus Antonius\'un Octavius Caesar\'a yenildikten sonra İskenderiye\'de anıt mezara kapanan Mısır Kraliçesi Kleopatra\'nın kendi canına kıymak için seçtiği yol nedir?', 'İncir sepeti içinde gizlice getirilen zehirli Nil engereğini (aspis yılanını) göğsüne ve koluna ısırtmak', ['Antonius\'un kanlı kılıcının üzerine atlayarak muhafızların gözü önünde kalbini delmek', 'Altın kadehin içinde eritilmiş inci ve baldıran zehrini şarapla karıştırıp içmek', 'İskenderiye Feneri\'nin en üst burcundan kendini Akdeniz sularına bırakmak'], 'Roma\'da zafer alayında teşhir edilmeyi gururuna yediremeyen Kleopatra, köylünün incir sepetinde getirdiği engerek yılanını göğsüne bastırarak kraliçe giysileri içinde ölümü seçer.'),
  ('Shakespeare\'in Venedik Taciri oyununda Portia\'nın babasının vasiyeti gereği Belmont\'a gelen taliplerin genç kadınla evlenebilmek için çözmek zorunda oldukları sınav nedir?', 'Altın, gümüş ve kurşun çekmecelerden Portia\'nın resmini barındıran doğru çekmeceyi (gösterişsiz kurşunu) seçmek', ['Sfenks bilmecesine benzeyen üç aşamalı Latince hukuk sorusuna hiç duraksamadan doğru yanıt vermek', 'Venedik dükünün düzenlediği gondol yarışında ve kılıç düellosunda diğer talipleri yenmek', 'Yüzük parmaklarındaki aile mührünü üç yıl boyunca hiç çıkarmadan deniz seferinden dönmek'], 'Fas Prensi altını, Aragon Prensi gümüşü seçip elenirken; dış görünüşün aldatıcılığını kavrayan Bassanio mütevazı kurşun çekmeceyi açarak Portia\'nın portresini bulur.'),
  ('Henrik Ibsen\'in "Hortlaklar" adlı oyununda "hortlaklar" metaforu aşağıdakilerden hangisini simgeler?', 'Geçmişten devralınan ölü gelenekleri, ahlaki ikiyüzlülükleri ve kalıtsal günahları', ['Eski İskandinav kalelerinde dolaştığına inanılan doğaüstü varlıkları', 'Sanayi Devrimi sonrasında işsiz kalan fabrika işçilerinin öfkesini', 'Savaş meydanlarında hayatını kaybeden askerlerin geride kalan anılarını'], 'Ibsen bu oyunda toplumun körü körüne bağlı kaldığı çürümüş değerleri ve geçmişin mirasını "hortlaklar" olarak nitelendirir.'),
  ('Kaplıca sularının kirli olduğunu kanıtladığı halde kasabanın ekonomik çıkarları yüzünden dışlanan Doktor Thomas Stockmann, Ibsen\'in hangi oyununun kahramanıdır?', 'Bir Halk Düşmanı', ['Yaban Ördeği', 'Yapı Ustası Solness', 'Denizden Gelen Kadın'], 'Doktor Stockmann gerçeği savunduğu için kasaba halkı ve yöneticiler tarafından "Bir Halk Düşmanı" ilan edilir.'),
  ('General kızı olmanın kibriyle sıkıcı bir evlilik içine hapsolan ve çevresindeki insanların kaderleriyle oynayarak trajik bir sona yürüyen Ibsen karakteri kimdir?', 'Hedda Gabler', ['Ellida Wangel', 'Hilde Wangel', 'Asta Allmers'], '"Hedda Gabler", Ibsen\'in psikolojik derinliği en yüksek ve yıkıcı kadın karakterlerinden biridir.'),
  ('Bir yönetmen, Ibsen\'in "Yapı Ustası Solness" oyununu sahnelerken Solness\'in baş dönmesine rağmen yüksek kuleye tırmanışını hangi temel çatışmayı vurgulamak için kullanmalıdır?', 'Yaşlanan sanatçının genç kuşağın enerjisi karşısındaki korkusu ile kendi sınırlarını aşma tutkusu arasındaki gerilimi', ['Orta Çağ katedral mimarisinin modern çelik konstrüksiyon yapılar karşısında uğradığı estetik yenilgiyi', 'İskandinav köylülerinin kentleşme sürecinde yaşadıkları barınma sorununu ve mülkiyet kavgasını', 'Kilise otoritesinin bağımsız zanaatkar loncaları üzerinde kurduğu ekonomik baskıyı'], 'Solness, genç Hilde Wangel\'in kışkırtmasıyla hem gençlikten duyduğu korkuyu yenmek hem de imkansızı başarmak isterken kulede düşüp ölür.'),
  ('Anton Çehov tiyatrosunda sıklıkla başvurulan "dolaylı eylem" (içsel aksiyon) tekniği aşağıdakilerden hangisiyle açıklanabilir?', 'Büyük trajik kırılmaların sahne dışında gerçekleşirken sahnede sıradan günlük konuşmaların ardındaki ruhsal gerilimin hissedilmesi', ['Oyuncuların duygularını doğrudan seyirciye dönerek yüksek sesli monologlarla ve abartılı jestlerle anlatması', 'Sahnede cinayet, düello ve intihar gibi çarpıcı fiziksel çatışmaların aralıksız biçimde gösterilmesi', 'Karakterlerin iç dünyalarını açıklamak üzere sahne kenarında bir anlatıcının sürekli yorum yapması'], 'Çehov\'da insanlar çay içerken ya da havadan sudan konuşurken hayatları sessizce parçalanır; asıl dram alt metindedir.'),
  ('Çehov\'un "Vişne Bahçesi" oyununda borçları yüzünden açık artırmayla satılan çiftliği satın alarak eski aristokrasinin yerini alan tüccar karakter kimdir?', 'Yermolay Lopahin', ['Pyotr Trofimov', 'Leonid Gayev', 'Boris Simeonov-Pişçik'], 'Serf kökenli zengin tüccar Lopahin, Ranevskaya ailesinin vişne bahçesini satın alıp ağaçları keserek yazlık evler yapmayı planlar.'),
  ('Çehov\'un "Üç Kız Kardeş" oyununda Olga, Maşa ve İrina\'nın taşra sıkıntısından kurtulmak için sürekli gitme özlemi duydukları şehir hangisidir?', 'Moskova', ['St. Petersburg', 'Paris', 'Viyana'], 'Prozorov kardeşlerin oyun boyunca tekrarladıkları "Moskova\'ya!" repliği, ulaşılamayan mutluluk ve geçmişe özlemin simgesidir.'),
  ('Yıllarca emek verip çiftliği yönettiği eniştesi Profesör Serebryakov\'un bencil ve sıradan biri olduğunu geç fark eden Çehov kahramanı kimdir?', 'Vanya Dayı', ['Doktor Mihail Astrov', 'Konstantin Treplev', 'Andrey Prozorov'], 'Vanya Dayı (İvan Voynitski), sözde bilgin Serebryakov uğruna gençliğini harcadığını anlayınca büyük bir varoluşsal bunalıma sürüklenir.'),
  ('Bernard Shaw\'un Ibsen etkisinde geliştirdiği "tartışma oyunu" (fikir tiyatrosu) anlayışının en belirgin özelliği nedir?', 'Karakterleri farklı toplumsal ve felsefi görüşlerin sözcüsü haline getirerek yerleşik önyargıları esprili bir diyalektikle çürütmesi', ['Diyalogları en aza indirerek insanın bilinçaltı korkularını ışık ve gölge oyunlarıyla dışavurması', 'Tarihsel olayları hiçbir yorum katmadan resmi arşiv belgelerinden birebir okuyarak aktarması', 'Yalnızca aristokrat sınıfın salon dedikodularını ahlaki bir yargı içermeksizin hafif bir dille sunması'], 'Fabian Sosyalizmini benimseyen Shaw, sahneyi keskin nüktelerle toplumsal ikiyüzlülüklerin tartışıldığı bir düşünsel platform olarak kullanmıştır.'),
  ('Bernard Shaw\'un "Bayan Warren\'ın Mesleği" adlı oyunu İngiltere\'de uzun yıllar hangi gerekçeyle sansüre uğramıştır?', 'Fuhuş olgusunu bireysel ahlaksızlık yerine kadınları yoksulluğa mahkum eden kapitalist sömürü düzeniyle açıklaması nedeniyle', ['Kraliçe Victoria ve kraliyet ailesi üyelerini sahnede doğrudan isimleriyle hicvetmesi nedeniyle', 'İngiliz ordusunun sömürgelerdeki askeri sırlarını yabancı devletlere ifşa etmesi nedeniyle', 'Kilise ayinlerini sahnede alaycı bir dille taklit ederek mezhep çatışmalarını kışkırtması nedeniyle'], 'Shaw, Bayan Warren\'ın genelev işletmeciliğini kapitalist sistemin kadın emeğine tanıdığı acımasız seçenekler üzerinden tartıştığı için sansürlenmiştir.'),
  ('Bernard Shaw\'un 1920\'de Azize ilan edilen Fransız ulusal kahramanının yargılanma sürecini tarihsel ve felsefi boyutlarıyla ele aldığı trajedisi hangisidir?', 'Ermiş Jeanne', ['Sezar ve Kleopatra', 'Binbaşı Barbara', 'Kırgınlar Evi'], '"Ermiş Jeanne" (Saint Joan), bireysel vicdan ve ulus bilincinin feodalizm ve kilise otoritesiyle çatışmasını işleyen başyapıttır.'),
  ('Bernard Shaw\'un Don Juan efsanesini tersyüz ederek Nietzsche ve Bergson etkisindeki "Yaşam Gücü" (Life Force) felsefesini tartıştığı kapsamlı oyunu hangisidir?', 'İnsan ve Üstün İnsan', ['Bayan Warren\'ın Mesleği', 'Kırgınlar Evi Fantezisi', 'Şeytanın Sadık Çömezi'], '"İnsan ve Üstün İnsan" (Man and Superman), özellikle üçüncü perdesindeki "Cehennemde Don Juan" sahnesiyle Shaw\'un felsefesini özetler.'),
  ('Luigi Pirandello\'nun "Altı Karakter Yazarını Arıyor" oyununda prova yapan tiyatro topluluğunun karşısına çıkan yarım bırakılmış karakterler hangi felsefi sorunu somutlaştırır?', 'Sanatsal biçimin değişmezliği ile akışkan insan yaşamının ve çok katmanlı gerçeğin çatışmasını', ['İtalyan tiyatro oyuncularının sendikal haklarını ve düşük ücretlerle çalışma koşullarını', 'Geleneksel İtalyan operasının modern sinema endüstrisi karşısında seyirci kaybetmesini', 'Yazarların telif haklarının tiyatro kumpanyaları tarafından yasa dışı biçimde gasp edilmesini'], 'Pirandello bu oyunda "yaşam" ile "biçim" (sanat), gerçek ile kurmaca arasındaki geçişkenliği ve sahne yanılsamasını sorgular.'),
  ('Attan düşerek hafızasını yitirdikten sonra kendisini 11. yüzyıl Alman İmparatoru sanan, iyileştiği halde acımasız gerçek dünyaya dönmemek için delilik rolünü sürdüren Pirandello karakteri kimdir?', 'IV. Enrico', ['Kont Leone Gala', 'Vali Yardımcısı Bay Ponza', 'Marki Carlo di Nolli'], 'Pirandello\'nun "IV. Enrico" (IV. Henry) adlı başyapıtında kahraman, bilinçli olarak delilik maskesinin ardına sığınmayı seçer.'),
  ('Pirandello\'nun "tiyatro içinde tiyatro" üçlemesini "Altı Karakter Yazarını Arıyor" ve "Bu Akşam Doğaçlama Yapıyoruz" ile birlikte tamamlayan üçüncü oyun hangisidir?', 'Herkes Kendi Rolünde', ['Dağların Devleri Masalı', 'Sicilya Turunçları Oyunu', 'Kraliyet Soytarısı Cıngırak'], '"Altı Karakter Yazarını Arıyor", "Herkes Kendi Rolünde" (Ciascuno a suo modo) ve "Bu Akşam Doğaçlama Yapıyoruz" Pirandello\'nun metatiyatro üçlemesidir.'),
  ('Lorca\'nın "Yerma" adlı trajedisinde adını İspanyolca "çorak/kısır" kelimesinden alan kadın kahramanın yaşadığı temel yıkım nedir?', 'Çocuk sahibi olma tutkusunun sevgisiz evliliği ve katı namus kuralları arasında imkansızlaşmasıyla kocasını öldürmesi', ['Kuraklık yüzünden kuruyan zeytin bahçelerini kurtarmak için tefecilere borçlanıp köyünden sürülmesi', 'Sevdiği gencin başka bir kızla evlenmesi üzerine düğün gecesi atla dağlara kaçması', 'İspanya İç Savaşı\'nda cepheye giden oğullarının ölüm haberini alarak aklını yitirmesi'], 'Yerma, annelik içgüdüsü ile toplumsal namus cenderesi arasında sıkışır; kocasının çocuk istemediğini kesin olarak anlayınca Juan\'ı boğarak kendi umudunu da öldürür.'),
  ('Lorca\'nın "Kanlı Düğün" oyununda düğün günü eski sevgilisi Leonardo ile kaçan Gelin ve Damat\'ın karanlık ormanda izini süren "Dilenci Kadın" ve "Ay" figürleri hangi işlevi görür?', 'Kaçınılmaz kaderi, yaklaşan ölümü ve kan dökme arzusunu şiirsel ve mitolojik simgelerle somutlaştırmak', ['Köylülerin düğün eğlencesini neşelendirmek için sahneledikleri geleneksel Endülüs kukla oyununu canlandırmak', 'Ormanda yolunu kaybeden aşıkları jandarmalardan gizleyerek sınır dışına çıkarmaya yardım etmek', 'Gerçekçi köy dramının ortasında seyirciyi güldürerek trajik gerilimi hafifletmek'], 'Lorca gerçekçi bir gazete haberinden yola çıktığı "Kanlı Düğün"ün üçüncü perdesinde "Ay" ve "Dilenci Kadın (Ölüm)" ile eseri gerçeküstü-şiirsel bir trajediye yükseltir.'),
  ('August Strindberg\'in "Matmazel Julie" adlı oyununun önsözünde açıkladığı doğalcı (natüralist) karakter anlayışı aşağıdakilerden hangisidir?', 'Tek boyutlu sabit tipler yerine kalıtım, sınıf, çevre ve anlık dürtülerle şekillenen karmaşık ve parçalı "ruhlar" yaratmak', ['İyi ve kötü karakterleri keskin çizgilerle ayırarak seyirciye doğrudan ahlak dersi vermek', 'Tarihteki kralları ve soyluları kusursuz bir irade gücüyle kadere meydan okuyan yarı-tanrılar olarak çizmek', 'İnsan davranışlarını toplumsal koşullardan tamamen bağımsız, rastlantısal mucizelerle açıklamak'], 'Strindberg, kontun kızı Julie ile uşak Jean arasındaki sınıf ve cinsiyet çatışmasını çok katmanlı psikolojik ve biyolojik nedenlerle açıklamıştır.'),
  ('Maksim Gorki\'nin yoksul bir barınakta yaşayan toplum dışı insanların hayallerini ve çaresizliğini anlattığı en ünlü gerçekçi tiyatro eseri hangisidir?', 'Ayaktakımı Arasında', ['Küçük Burjuvalar', 'Güneşin Çocukları', 'Yaz Misafirleri'], 'Gorki\'nin 1902\'de Moskova Sanat Tiyatrosu\'nda sahnelenen "Ayaktakımı Arasında" (Diplerde) adlı oyunu, toplumsal gerçekçi tiyatronun başyapıtlarından biridir.'),
  ('Gerçekçi ve doğalcı tiyatroda sıkça kullanılan "dördüncü duvar" kavramı ne anlama gelir?', 'Sahnenin seyirciye bakan ön kısmında görünmez bir duvar varmışçasına oyuncuların seyirciyi yok sayarak doğal davranması', ['Sahnenin üç yanının tamamen yıkılarak izleyicilerin oyuncuları çepeçevre sarması', 'Tiyatro binasının dış cephesine oyunun siyasi mesajlarını içeren dev afişler asılması', 'Dekor maliyetini düşürmek için sahne arkasındaki tuğla duvarın boyanmadan çıplak bırakılması'], '"Dördüncü duvar" yanılsaması, seyircinin sanki bir odanın kaldırılmış duvarından gerçek insanların özel yaşamını gözetliyormuş gibi hissetmesini sağlar.'),
  ('Oyuncunun canlandırdığı karakterin iç dünyasıyla özdeşleşmesini sağlayan "coşku belleği" ve "büyülü eğer" kavramlarını geliştiren Rus tiyatro kuramcısı kimdir?', 'Konstantin Stanislavski', ['Vsevolod Meyerhold', 'Yevgeni Vahtangov', 'Mihail Çehov'], 'Stanislavski Sistemi, oyuncunun mekanik taklit yerine psikolojik gerçeklik ve "Ben bu koşullarda olsaydım ne yapardım?" (büyülü eğer) sorusuyla rol yaratmasına dayanır.'),
  ('Oscar Wilde\'ın Fransızca olarak kaleme aldığı, İncil\'deki Yahya Peygamber\'in (Vaftizci Yahya) başının kesilmesi kıssasını dekadan ve sembolist bir atmosferle işleyen tek perdelik trajedisi hangisidir?', 'Salome', ['Lady Windermere\'in Yelpazesi', 'İdeal Bir Koca', 'Önemsiz Bir Kadın'], 'Wilde\'ın Sarah Bernhardt düşünülerek Fransızca yazdığı "Salome", Richard Strauss\'un operasına da kaynaklık etmiş sembolist bir trajedidir.'),
  ('Belçikalı sembolist yazar Maurice Maeterlinck\'in iki çocuğun mutluluğu aramak üzere çıktıkları düşsel yolculuğu anlatan ünlü masalsı oyunu hangisidir?', 'Mavi Kuş', ['Pelléas ile Mélisande', 'Körler', 'Davetsiz Misafir'], 'Maeterlinck\'in "Mavi Kuş" adlı eseri, mutluluğun uzaklarda değil insanın kendi evinde ve paylaşmada olduğunu anlatan sembolist bir başyapıttır.'),
  ('"Tiresias\'ın Memeleri" adlı oyununun önsözünde "sürrealist" (gerçeküstücü) terimini ilk kez kullanarak modern sanat literatürüne kazandıran Fransız şair ve yazar kimdir?', 'Guillaume Apollinaire', ['André Breton', 'Paul Éluard', 'Louis Aragon'], 'Apollinaire, 1917\'de sahnelenen "Tiresias\'ın Memeleri" adlı oyununu "drame surréaliste" olarak nitelendirerek bu kavramı ilk kez kullanmıştır.'),
  ('İrlanda Ulusal Tiyatrosu\'nun (Abbey Theatre) öncülerinden John Millington Synge\'in, babasını öldürdüğünü söyleyerek bir köyde kahraman ilan edilen genci anlattığı ünlü kara komedyası hangisidir?', 'Batı Dünyasının Babayiğidi', ['Denize Giden Atlıların Dramı', 'Azizlerin Gölgesindeki Kuyu', 'Gezgin Tenekecinin Düğünü'], 'Synge\'in 1907\'de Dublin\'de olaylara yol açan "The Playboy of the Western World" (Batı Dünyasının Babayiğidi) adlı eseri, mit yaratma ve gerçeklik çatışmasını işler.'),
  ('Alman dışavurumcu (ekspresyonist) tiyatrosunun öncülerinden Frank Wedekind\'in ergenlik çağındaki gençlerin cinsel uyanışını ve baskıcı eğitim sisteminin yol açtığı yıkımı işlediği 1891 tarihli oyunu hangisidir?', 'Bahar Uyanışı', ['Lulu', 'Pandora\'nın Kutusu', 'Marquis von Keith'], 'Wedekind\'in "Bahar Uyanışı" (Frühlings Erwachen), ikiyüzlü yetişkin ahlakının gençleri intihara ve ölüme sürükleyişini dışavurumcu öğelerle eleştirir.'),
  ('Alman dışavurumcu yazar Georg Kaiser\'in modern makineleşmenin ve kapitalist hızın insanı nasıl köleleştirdiğini anlattığı en bilinen eserlerinden biri hangisidir?', 'Sabahtan Geceyarısına', ['Fizikçiler', 'Yaşlı Hanımın Ziyareti', 'Biedermann ve Kundakçılar'], 'Georg Kaiser\'in "Sabahtan Geceyarısına" ve "Gaz" üçlemesi, Alman dışavurumcu tiyatrosunun en temel metinlerindendir.'),
  ('"Robot" sözcüğünü dünya dillerine kazandıran "R.U.R. (Rossum\'un Evrensel Robotları)" adlı bilimkurgu-eleştiri oyununun Çek yazarı kimdir?', 'Karel Čapek', ['Václav Havel', 'Jaroslav Hašek', 'Milan Kundera'], 'Karel Čapek, kardeşi Josef\'in önerdiği Çekçe "robota" (angarya/zorunlu çalışma) kelimesinden türetilen "Robot"u 1920 tarihli "R.U.R." oyununda kullanmıştır.'),
  ('İrlandalı yazar Sean O\'Casey\'nin 1916 Paskalya Ayaklanması ve İrlanda İç Savaşı sırasında Dublin gecekondularında yaşayan yoksul ailelerin trajikomik dramını anlattığı ünlü oyunu hangisidir?', 'Juno ve Tavuskuşu', ['Gümüş Kupa', 'Kızıl Güller Benim İçin', 'Piskoposun Şenlik Ateşi'], 'Sean O\'Casey\'nin Dublin Üçlemesi\'nde yer alan "Juno ve Tavuskuşu" (ve "Saban ve Yıldızlar"), savaşın bedelini ödeyen yoksul kadınların direncini anlatır.'),
  ('Eugene O\'Neill\'in kendi ailesinin uyuşturucu bağımlılığı, alkolizm ve suçluluk duygularıyla dolu trajik geçmişini "Tyrone" ailesi üzerinden anlattığı otobiyografik başyapıtı hangisidir?', 'Günden Geceye', ['Karaağaçlar Altında Arzu', 'Dondurmacı Geliyor', 'İmparator Jones'], 'Ölümünden sonra sahnelenmesini vasiyet ettiği "Long Day\'s Journey Into Night" (Günden Geceye), modern Amerikan gerçekçi trajedisinin zirvelerindendir.'),
  ('Eugene O\'Neill\'in "Dondurmacı Geliyor" (The Iceman Cometh) adlı oyununda Harry Hope\'un barında toplanan düşkün insanların "yarın" umutlarını yıkan gezgin satıcı Hickey neyi temsil eder?', 'İnsanları ayakta tutan hayalleri yok ettiğinde yaşam sevincini de öldüren acımasız ve ölümcül hakikat saplantısını', ['Amerikan Rüyası\'nı herkese ulaştıran başarılı girişimcilik ve çalışkanlık ruhunu', 'İçki yasağı döneminde yoksul mahalleleri denetleyen dürüst federal emniyet güçlerini', 'Ekonomik krizden çıkış için sendikal örgütlenmeyi savunan devrimci işçi önderliğini'], 'Ibsen ve Gorki\'deki "yaşam yalanı" temasını sürdüren O\'Neill, Hickey karakteriyle yanılsamaları yıkmanın insanları ölüme yaklaştırdığını gösterir.'),
  ('Amerikalı oyun yazarı Thornton Wilder\'ın dekorsuz sahne kullanımı ve doğrudan seyirciyle konuşan "Sahne Amiri" figürüyle sıradan insan yaşamının değerini anlattığı Pulitzer ödüllü oyunu hangisidir?', 'Bizim Şehir', ['Çöpçatan', 'Kıl Payı', 'San Luis Rey Köprüsü'], 'Thornton Wilder\'ın 1938 tarihli "Bizim Şehir" (Our Town) adlı eseri, Grover\'s Corners kasabasındaki doğum, evlilik ve ölümü yalın ve yanılsamasız bir sahneyle anlatır.'),
  ('Alman yönetmen Erwin Piscator\'un 1920\'lerde film projeksiyonları, yürüyen bantlar ve tarihsel istatistikler kullanarak geliştirdiği ve Brecht\'i de etkileyen tiyatro anlayışı nasıl adlandırılır?', 'Politik Tiyatro', ['Absürt Tiyatro', 'Oda Tiyatrosu', 'Sembolist Tiyatro'], 'Erwin Piscator, "Politik Tiyatro" kitabıyla sahneyi bireysel psikolojiden çıkarıp tarihsel-toplumsal güçlerin belgesel arenası haline getirmiştir.'),
  ('Bertolt Brecht\'in epik tiyatro kuramında merkezi bir yer tutan "Yabancılaştırma Efekti" (Verfremdungseffekt) seyircide hangi tutumu geliştirmeyi amaçlar?', 'Duygusal özdeşleşmeyi kırarak seyircinin sahnedeki toplumsal olayları eleştirel ve sorgulayıcı bir akılla değerlendirmesini', ['Seyircinin kahramanın acılarıyla bütünleşip gözyaşı dökerek ruhsal bir arınma (katarsis) yaşamasını', 'İzleyicinin dış dünyadaki ekonomik ve siyasal sorunları iki saatliğine tamamen unutup dinlenmesini', 'Oyuncuların yabancı dillerde konuşarak yalnızca seçkin ve eğitimli bir zümreye hitap etmesini'], 'Brecht, seyircinin hipnotize olmuş gibi sahneye kapılmasını engelleyip "Bu durum değişebilir mi?" sorusunu sormasını ister.'),
  ('Brecht\'in "Sezuan\'ın İyi İnsanı" adlı oyununda iyiliksever fahişe Şen Te\'nin acımasız ekonomik düzende ayakta kalabilmek için büründüğü katı yürekli kuzen kimliği nedir?', 'Şui Ta', ['Azdak', 'Macheath', 'Puntila'], 'Şen Te, sömürülmemek için acımasız "kuzen Şui Ta" maskesini takmak zorunda kalır; Brecht böylece bozuk düzende tek başına iyi kalmanın imkansızlığını tartışır.'),
  ('Brecht\'in "Kafkas Tebeşir Dairesi" oyununda terk edilmiş çocuğu doğuran soylu kadına değil, ona emek verip büyüten hizmetçi Gruşa\'ya veren halk yargıcı kimdir?', 'Azdak', ['Schweyk', 'Arturo Ui', 'Bay Keuner'], 'Yargıç Azdak, tebeşir dairesi sınavıyla mülkiyetin ve anneliğin kan bağına değil, emeğe ve şefkate ait olduğuna hükmeder.'),
  ('Brecht\'in besteci Kurt Weill ile birlikte İngiliz yazar John Gay\'in "Dilenciler Operası"ndan uyarladığı, yeraltı dünyasıyla burjuva düzenini eşitleyen ünlü müzikli oyunu hangisidir?', 'Üç Kuruşluk Opera', ['Mahagonny Kentinin Yükselişi ve Düşüşü', 'Önlem', 'Evet Diyen ile Hayır Diyen'], '"Banka kurmak, banka soymaktan daha büyük suç değil midir?" sorusuyla özetlenen "Üç Kuruşluk Opera", Sustalı Mack karakteriyle ünlenmiştir.'),
  ('Adolf Hitler\'in ve Nazizmin yükselişini 1930\'lar Şikago\'sundaki karnabahar tröstünü ele geçiren bir gangster çetesi alegorisiyle anlatan Brecht oyunu hangisidir?', 'Arturo Ui\'nin Önlenebilir Yükselişi', ['Üçüncü Reich\'ın Korku ve Sefaleti', 'Carrar Ana\'nın Silahları', 'İkinci Dünya Savaşı\'nda Şvayk'], 'Brecht, "Arturo Ui\'nin Önlenebilir Yükselişi" ile faşizmin doğaüstü bir kader değil, ekonomik çıkarlarla desteklenen önlenebilir bir suç şebekesi olduğunu gösterir.'),
  ('Eleştirmen Martin Esslin\'in Albert Camus\'nün "Sisifos Söyleni"nden ödünç alarak adlandırdığı "Absürt Tiyatro"nun (Uyumsuz Tiyatro) temel biçimsel özelliği nedir?', 'İnsan varoluşunun anlamsızlığını mantıklı tartışmalarla anlatmak yerine, mantığı ve dili parçalayarak doğrudan sahne imgesine dönüştürmesi', ['Toplumsal devrim için işçilere somut eylem planları sunan gerçekçi ve iyimser fabrika oyunları üretmesi', 'Klasik Yunan trajedilerindeki koro ve kader anlayışını kafiyeli dizelerle yeniden canlandırması', 'Tarihsel savaşları kronolojik sırayla ve resmi devlet belgelerine dayanarak belgeselleştirmesi'], 'Esslin\'e göre Sartre ve Camus uyumsuzluğu geleneksel ve mantıklı diyaloglarla tartışırken, Beckett ve Ionesco uyumsuzluğu biçimin kendisi haline getirmiştir.'),
  ('Samuel Beckett\'in "Oyun Sonu" (Endgame) adlı eserinde tekerlekli sandalyeye mahkum kör efendi Hamm\'in yanı başında çöp bidonları içinde yaşayan karakterler kimlerdir?', 'Hamm\'in bacaklarını yitirmiş anne ve babası Nagg ile Nell', ['Yolculuktan dönen gezgin tüccar Pozzo ile uşağı Lucky', 'Kasabanın belediye başkanı ile emekli istasyon şefi', 'Sirkten kaçmış iki yaşlı palyaço ile kemancı'], '"Oyun Sonu"nda Nagg ve Nell adlı yaşlı ebeveynlerin çöp kutuları içinde yaşaması, iletişimsizliği ve bedensel-varoluşsal çöküşü simgeler.'),
  ('Samuel Beckett\'in yaşlı ve yalnız bir adamın geçmişte farklı yaşlarında kaydettiği ses bantlarını dinleyerek kendi gençliğiyle hesaplaşmasını anlatan tek kişilik oyunu hangisidir?', 'Krapp\'ın Son Bandı', ['Sözsüz Oyun', 'Geliş ve Gidiş', 'Felaket'], '"Krapp\'ın Son Bandı", bellek, zamanın yıkıcılığı ve yabancılaşan benlik temalarını teyp kaydı aracılığıyla işleyen çarpıcı bir monologdur.'),
  ('Eugène Ionesco\'nun bir İngilizce konuşma kılavuzundaki basmakalıp cümlelerden esinlenerek yazdığı ve "karşı-oyun" (anti-pièce) adını verdiği ilk eseri hangisidir?', 'Kel Şarkıcı', ['Gergedanlar', 'Kral Ölüyor', 'Macbett'], 'Bay ve Bayan Smith ile Martin çiftinin birbirini tanımayacak kadar yabancılaştığı "Kel Şarkıcı", burjuva yaşamının mekanikleşmesini ve dilin iflasını hicveder.'),
  ('Eugène Ionesco\'nun "Gergedanlar" adlı oyununda küçük bir kasabadaki insanların tek tek gergedana dönüşürken yalnızca Bérenger karakterinin insan kalmakta direnmesi neyin alegorisidir?', 'Bireylerin faşizm, totalitarizm ve kitle psikolojisi karşısında sürüleşmesine direnen vicdanın', ['Çevre kirliliği yüzünden nesli tükenen yaban hayvanlarını koruma bilincinin', 'Afrika sömürgelerinden Avrupa\'ya taşınan salgın hastalıkların yarattığı tıbbi paniğin', 'Modern kentleşme sürecinde hayvanat bahçelerinin şehir dışına taşınması tartışmasının'], 'Ionesco, Romanya\'da tanık olduğu faşistleşme sürecinden yola çıkarak ideolojik fanatizmin ve konformizmin insanları nasıl canavarlaştırdığını "gergedanlaşma" imgesiyle anlatmıştır.'),
  ('Ionesco\'nun özel ders alan genç bir öğrencinin, profesörün otoriter dil baskısı altında giderek edilgenleşip sonunda profesör tarafından bıçaklanarak öldürülmesini işlediği tek perdelik oyunu hangisidir?', 'Ders', ['Kurbanlar Görev Başına', 'Amédée ya da Nasıl Kurtulmalı', 'Yeni Kiracı'], '"Ders" (La Leçon), dilin ve bilginin bir tahakküm, şiddet ve iktidar aracına dönüşmesini grotesk bir komik-trajediyle sergiler.'),
  ('Arthur Miller\'ın 1692 yılındaki Salem cadı mahkemelerini konu alan "Cadı Kazanı" (The Crucible) adlı eseri yazıldığı 1950\'li yılların Amerika\'sındaki hangi siyasal olayı alegorik olarak eleştirir?', 'Senatör McCarthy öncülüğünde aydınlara ve sanatçılara karşı yürütülen antikomünist cadı avını ve muhbirlik baskısını', ['İkinci Dünya Savaşı sonrasında ordudan terhis edilen askerlerin yaşadığı konut ve işsizlik krizini', 'Güney eyaletlerindeki tarım işçilerinin sendikalaşma mücadelesine karşı uygulanan ekonomik ambargoyu', 'Nükleer silah denemelerinin Nevada çölündeki yerleşim yerlerinde yarattığı radyasyon korkusunu'], 'John Proctor\'un arkadaşlarını ihbar etmeyi reddedip adını ve onurunu korumak uğruna idama yürümesi, McCarthy dönemi sorgulamalarına karşı ahlaki bir duruştur.'),
  ('Arthur Miller\'ın "Hepsi Oğullarımdı" (All My Sons) adlı oyununda Joe Keller karakterinin vicdani yıkımına yol açan geçmişteki suçu nedir?', 'İkinci Dünya Savaşı sırasında orduya çatlak uçak motoru parçaları satarak yirmi bir pilotun ölümüne neden olması', ['Büyük Buhran yıllarında ortağının banka hesaplarını zimmetine geçirerek yurt dışına kaçması', 'Oğlunun sevdiği kızı ailesinden ayırmak için göçmenlik bürosuna gizli ihbarda bulunması', 'Fabrikasındaki grevi kırmak amacıyla silahlı çeteler kiralayıp işçi temsilcilerini vurdurması'], 'Ailesinin refahı için suçu ortağına yıkan Joe Keller, ölen oğlunun mektubuyla tüm pilotların aslında kendi "oğulları" olduğunu kavrayınca intihar eder.'),
  ('Arthur Miller\'ın Brooklyn liman işçisi Eddie Carbone\'nin büyüttüğü yeğeni Catherine\'e duyduğu bastırılmış tutkuyu ve İtalyan göçmen akrabalarını ihbar edişini Antik Yunan trajedisi kurgusuyla anlattığı eseri hangisidir?', 'Köprüden Görünüş', ['Düşüşten Sonra', 'Vichy\'de Olay', 'Bedel'], 'Avukat Alfieri\'nin Antik koro gibi anlatıcılık yaptığı "Köprüden Görünüş" (A View from the Bridge), tutku ve toplumsal onur yasasının çarpışmasını anlatır.'),
  ('Tennessee Williams\'ın "İhtiras Tramvayı" (Arzu Tramvayı) adlı oyununda geçmişteki aristokratik hayallerine sığınan kırılgan Blanche DuBois ile çatışan kaba ve acımasız enişte karakteri kimdir?', 'Stanley Kowalski', ['Tom Wingfield', 'Brick Pollitt', 'Big Daddy'], 'Blanche DuBois çöken eski Güney\'in inceliğini ve yanılsamalarını, Stanley Kowalski ise acımasız, dürtüsel ve kaba yeni gerçekliği temsil eder.'),
  ('Tennessee Williams\'ın bir "anı oyunu" olarak kurguladığı "Sırça Kümes"te (Camdan Hayvan Koleksiyonu) engelli kız kardeş Laura\'nın camdan tekboynuzlu at figürü neyi simgeler?', 'Laura\'nın dış dünyanın sertliğine dayanamayan aşırı kırılgan iç dünyasını ve kalabalıklar içindeki benzersiz yalnızlığını', ['Wingfield ailesinin borsada kaybettiği büyük servetten geriye kalan son antika mirası', 'Ağabeyi Tom\'un deniz aşırı ülkelere yapacağı ticari yolculuklardan kazanacağı zenginliği', 'Annesi Amanda\'nın gençlik yıllarında katıldığı güzellik yarışmalarında kazandığı kupayı'], 'Misafir Jim ile dans ederken boynuzu kırılan cam at, Laura\'nın incinebilirliğini ama aynı zamanda kırılınca "diğer atlara benzeyerek" gerçeklikle temasını simgeler.'),
  ('Edward Albee\'nin Central Park\'taki bir bankta oturan konformist burjuva Peter ile toplum dışı yalnız Jerry arasındaki tedirgin edici karşılaşmayı ve kanlı sonu anlatan tek perdelik absürt oyunu hangisidir?', 'Hayvanat Bahçesi Öyküsü', ['Kum Havuzu', 'Amerikan Rüyası', 'Narin Denge'], '1958 tarihli "Hayvanat Bahçesi Öyküsü" (The Zoo Story), modern metropol insanının yalıtılmışlığını ve iletişim kurabilmek için şiddete başvuracak denli çaresizleşmesini işler.'),
  ('Harold Pinter\'ın erken dönem oyunları için kullanılan "Tehdit Komedyası" (Comedy of Menace) kavramı nasıl bir atmosferi tanımlar?', 'Güvenli görünen sıradan bir odaya dışarıdan gelen belirsiz yabancıların girmesiyle gündelik konuşmaların altında büyüyen nedensiz korku ve iktidar savaşını', ['Orta Çağ şatolarında geçen hayalet hikayelerinin neşeli şarkılarla parodileştirilmesini', 'Dedektiflerin ipuçlarını takip ederek katili son sahnede yakaladığı klasik polisiye gerilimi', 'Sirk palyaçolarının tehlikeli akrobasi hareketleri yaparken seyirciyi güldürmesini'], '"Oda", "Doğum Günü Partisi" ve "Gitgel Dolap" gibi oyunlarda sıradan mekanlar bir anda nedeni tam açıklanmayan bir kuşatma ve baskı alanına dönüşür.'),
  ('Harold Pinter\'ın evlilik dışı bir aşk üçgenini sondan başa doğru geriye akan bir zaman kurgusuyla (1977\'den 1968\'e) anlattığı ünlü oyunu hangisidir?', 'Aldatma', ['Kapıcı', 'Eve Dönüş', 'Eski Zamanlar'], 'Pinter\'ın "Aldatma" (Betrayal) adlı eseri, ilişkilerdeki aldatmacaları ters kronolojiyle açığa çıkararak belleğin ironisini sergiler.'),
  ('Shakespeare\'in "Hamlet" trajedisindeki iki önemsiz yan karakteri başrole taşıyarak varoluşu, rastlantıyı ve kaderi absürt-felsefi bir komedyayla sorgulayan Tom Stoppard eseri hangisidir?', 'Rosencrantz ve Guildenstern Öldüler', ['Arkadia', 'Travestiler', 'Gerçek Şey'], 'Tom Stoppard\'ın 1966 tarihli "Rosencrantz ve Guildenstern Öldüler" oyunu, yazı-tura sahnesiyle başlayan parlak bir üst-tiyatro ve absürt klasiktir.'),
  ('1956\'da sahnelenen "Öfkeyle Geriye Bak" (Look Back in Anger) adlı oyunuyla İngiliz tiyatrosunda "Öfkeli Genç Adamlar" (Mutfak Lavabosu Gerçekçiliği) akımını başlatan yazar kimdir?', 'John Osborne', ['Arnold Wesker', 'Terence Rattigan', 'Noël Coward'], 'John Osborne\'un Jimmy Porter karakteri, savaş sonrası İngiltere\'sinin sınıf ayrımlarına ve uyuşukluğuna isyan eden kuşağın sesi olmuştur.'),
  ('Varoluşçu ve uyumsuz felsefenin öncüsü Albert Camus\'nün karısının ölümünden sonra sınırsız gücün mantığını uç noktaya taşıyarak "ay\'ı isteyen" Roma İmparatorunu anlattığı trajedisi hangisidir?', 'Caligula', ['Yanlışlık', 'Sıkıyönetim', 'Adiller'], 'Camus\'nün "Caligula"sı, "İnsanlar ölüyor ve mutlu değiller" gerçeğiyle sarsılan imparatorun mutlak özgürlük arayışını yıkıcı bir zorbalığa dönüştürmesini işler.'),
  ('Albert Camus\'nün yirmi yıl sonra zengin olarak evine dönen ama kimliğini gizleyen bir oğulun, otel işleten annesi ve kız kardeşi tarafından tanınmayıp parası için öldürülmesini anlatan oyunu hangisidir?', 'Yanlışlık', ['Düşüş', 'Yabancı', 'Veba'], 'Camus\'nün "Yabancı" romanında da gazete haberi olarak geçen bu öykü, "Yanlışlık" (Le Malentendu) oyununda iletişimsizlik ve uyumsuz kader trajedisine dönüşür.'),
  ('Fransız yazar Jean Genet\'nin efendileri evde yokken sırayla "Hanımefendi" rolüne bürünen Claire ve Solange adlı iki kız kardeşi anlattığı törensel-absürt başyapıtı hangisidir?', 'Hizmetçiler', ['Balkon', 'Zenciler', 'Paravanlar'], 'Jean Genet\'nin "Hizmetçiler" (Les Bonnes) adlı eseri, ezilenlerin ezenlerin kimliğine duyduğu nefret ve hayranlık sarmalını törensel bir rol oyunuyla açığa çıkarır.'),
  ('Friedrich Dürrenmatt\'ın bir akıl hastanesinde kendilerini Newton ve Einstein sanan hastaların ve dünyayı yok edecek formülünü gizlemek için deli taklidi yapan Möbius\'un öyküsünü anlattığı bilim-ahlak oyunu hangisidir?', 'Fizikçiler', ['Göktaşı', 'Kral John', 'Suç Ortakları'], 'Brecht\'in "Galileo"suna grotesk bir yanıt niteliğindeki "Fizikçiler"de, Möbius dünyayı kurtarmak için tımarhaneye sığınır; ancak başhekim Doktor von Zahnd formülleri çoktan ele geçirmiştir.'),
  ('İsviçreli yazar Max Frisch\'in evlerine aldıkları kundakçıların benzin bidonlarını ve fitilleri hazırlamasına göz yuman korkak burjuva Biedermann\'ı anlattığı "ahlaksız bir ders oyunu" alt başlıklı eseri hangisidir?', 'Biedermann ve Kundakçılar', ['Andorra', 'Don Juan ya da Geometri Aşkı', 'Çin Seddi'], 'Max Frisch\'in "Biedermann ve Kundakçılar"ı, yıkıcı totaliter güçlerle uzlaşarak kurtulacağını sanan konformist aydının ve burjuvanın aymazlığını taşlar.'),
  ('Alman yazar Peter Weiss\'ın Fransız Devrimi sonrası Charenton Akıl Hastanesi\'nde Marquis de Sade\'ın yönetiminde akıl hastalarının Jean-Paul Marat\'nın öldürülmesini sahnelemesini anlatan ünlü oyunu hangisidir?', 'Marat/Sade', ['Soruşturma', 'Troçki Sürgünde', 'Hölderlin'], 'Uzun adı "Marat\'nın Zulüm Görmesi ve Öldürülmesi..." olan "Marat/Sade", hem Brechtçi yabancılaştırmayı hem de Artaudcu Vahşet Tiyatrosunu birleştiren eşsiz bir başyapıttır.'),
  ('Fransız yazar Jean Anouilh\'in Sophokles\'in ünlü trajedisini modern bir dille yeniden yorumlayarak II. Dünya Savaşı sırasında uzlaşmacı devlet aklı (Kreon) ile mutlak ahlaki direnişi karşılaştırdığı eseri hangisidir?', 'Antigone', ['Becket ya da Tanrının Onuru', 'Tarlakuşu', 'Yolcular'], 'Jean Anouilh\'in 1944\'te sahnelenen "Antigone"si, Kreon\'un pragmatik "evet"ine karşı Antigone\'nin tavizsiz "hayır" diyebilme iradesini modern insana taşır.'),
  ('Fransız oyun yazarı Jean Giraudoux\'nun Truva Savaşı\'nın patlak vermesini önlemeye çalışan Hektor ile savaş çığırtkanlarını karşı karşıya getirerek yaklaşan II. Dünya Savaşı tehlikesini uyardığı eseri hangisidir?', 'Truva Savaşı Olmayacak', ['Chaillot\'nun Deli Kadını', 'Ondine', 'İntermezzo'], 'Giraudoux\'nun 1935 tarihli "Truva Savaşı Olmayacak" adlı eseri, diplomatik kibir ve milliyetçi kışkırtmaların barış çabalarını nasıl boşa çıkardığını ironiyle işler.'),
  ('Dario Fo\'nun 1969 Milano bombalaması sonrası emniyet müdürlüğü penceresinden düşerek ölen demiryolu işçisi Giuseppe Pinelli olayından yola çıkarak polis sorgularındaki çelişkileri teşhir ettiği eseri hangisidir?', 'Bir Anarşistin Kaza Sonucu Ölümü', ['Ödenmeyecek! Ödemiyoruz!', 'Klakson, Borazanlar ve Bıdıklar', 'Kadın Oyunları'], 'Oyunda "Deli" karakteri sorgu yargıcı kılığına girerek emniyet görevlilerinin uydurduğu resmi raporları kendi mantıklarıyla çürütüp gülünç düşürür.'),
  ('Polonyalı yönetmen ve kuramcı Jerzy Grotowski\'nin 1960\'larda ortaya koyduğu "Yoksul Tiyatro" (Poor Theatre) kavramı tiyatro sanatını hangi öze indirgemeyi savunur?', 'Dekor, kostüm, makyaj ve ışık efektleri gibi tüm dışsal fazlalıkları atarak tiyatroyu oyuncu ile seyirci arasındaki canlı ve kutsal buluşmaya indirgemeyi', ['Yalnızca ekonomik durumu yetersiz kenar mahallelerde ücretsiz sokak gösterileri düzenlemeyi', 'Profesyonel oyuncuları sahneden uzaklaştırıp yalnızca eğitimsiz amatör işçilerle oyun çıkarmayı', 'Büyük edebi klasikleri yasaklayarak yalnızca günlük gazete haberlerini sahnede okumayı'], 'Grotowski\'ye göre tiyatro sinema ve televizyonla görsel teknoloji açısından yarışamaz; tiyatronun vazgeçilmez özü oyuncunun bedeni/ruhu ile seyircinin doğrudan karşılaşmasıdır.'),
  ('Brezilyalı tiyatro kuramcısı Augusto Boal\'in Brecht\'ten de ilerleyerek geliştirdiği "Ezilenlerin Tiyatrosu" ve "Forum Tiyatro" yönteminde "seyirci-oyuncu" (spect-actor) kavramı neyi ifade eder?', 'Seyircinin edilgen izleyici konumundan çıkıp sahneye müdahale ederek ezilen karakterin yerine geçmesi ve baskıya karşı çözüm yollarını bizzat denemesi', ['Tiyatro eleştirmenlerinin oyun başlamadan önce sahneye çıkıp yazarın biyografisini anlatması', 'Oyuncuların birinci perde sonunda salona inip ikinci perdeyi koltuklarda oturarak izlemesi', 'Sokaktan geçen rastgele insanların habersizce gizli kameralarla kaydedilerek dev ekrana yansıtılması'], 'Boal, tiyatroyu "devrimin bir provası" olarak görmüş ve seyircinin sahnedeki haksızlığı durdurup aksiyonu değiştirdiği katılımcı "Forum Tiyatro"yu kurmuştur.'),
  ('Polonyalı absürt ve politik oyun yazarı Sławomir Mrożek\'in açık denizde salda mahsur kalan üç kazazedenin kimin yenileceğine demokratik kurallar ve nutuklarla karar vermesini taşladığı tek perdelik oyunu hangisidir?', 'Açık Denizde', ['Tango', 'Sığıntılar', 'Striptiz'], 'Mrożek\'in "Açık Denizde" adlı keskin politik parodisinde, güçlülerin zayıf olanı kendini feda etmeye ikna etmek için özgürlük ve adalet söylemlerini nasıl çarpıttığı anlatılır.'),
  ('İspanya doğumlu Fransız yazar Fernando Arrabal\'ın savaş cephesindeki genç asker Zapo\'nun anne-babasıyla cephede piknik yapmasını çocuksu bir saflık ve kara mizahla anlatan savaş karşıtı absürt oyunu hangisidir?', 'Cephede Piknik', ['Otomobil Mezarlığı', 'Mimar ve Asur İmparatoru', 'Fando ile Lis'], 'Arrabal\'ın "Cephede Piknik" adlı oyununda düşman askeri Zepo da pikniğe katılır; savaşın saçmalığı tam barışçıl bir oyun kurulmuşken yağan bombalarla gözler önüne serilir.'),
  ('Nobel ödüllü İngiliz şair ve oyun yazarı T. S. Eliot\'ın 1170 yılında Başpiskopos Thomas Becket\'in kralın şövalyeleri tarafından öldürülmesini manzum trajedi biçiminde işlediği eseri hangisidir?', 'Katedralde Cinayet', ['Kokteyl Parti', 'Aile Toplantısı', 'Gizli Katip'], 'T. S. Eliot, 20. yüzyılda manzum ve dinsel-felsefi trajediyi yeniden canlandırdığı "Katedralde Cinayet"te (Murder in the Cathedral) şehitlik ile kibir arasındaki ince çizgiyi sorgular.'),
  ('Amerikalı yazar Sam Shepard\'ın dağılmış Amerikan ailesini, baba-oğul çatışmasını ve Amerikan taşrasının karanlık sırlarını simgesel bir gerçekçilikle işlediği Pulitzer ödüllü oyunu hangisidir?', 'Gömülü Çocuk', ['Vahşi Batı', 'Aç Sınıfın Laneti', 'Aşk Delisi'], 'Sam Shepard\'ın aile üçlemesi içinde yer alan "Gömülü Çocuk" (Buried Child), bereketini ve masumiyetini yitirmiş Amerikan kırsal mitini sarsıcı bir sır etrafında yıkar.'),
  ('Amerikalı yazar David Mamet\'in acımasız emlak satıcıları arasındaki kıyasıya rekabeti, ahlaki çöküşü ve kesik, sert konuşma dilini ("Mametspeak") sergilediği Pulitzer ödüllü oyunu hangisidir?', 'Glengarry Glen Ross', ['Oleanna', 'Amerikan Bufalosu', 'Boston Evliliği'], '"Glengarry Glen Ross", vahşi kapitalist satış baskısı altında ezilen ve ayakta kalmak için hırsızlığa sürüklenen çalışanların dünyasını diyalog ustalığıyla yansıtır.'),
  ('İngiliz sosyalist oyun yazarı Edward Bond\'un Londra varoşlarındaki işsiz ve yabancılaşmış gençlerin parktaki bebek arabasındaki bir bebeği taşlayarak öldürmesi sahnesiyle sansürü sarsan 1965 tarihli oyunu hangisidir?', 'Kurtarılmış', ['Lear', 'Deniz', 'Dar Yol Kuzeye Çıkar'], 'Edward Bond\'un "Kurtarılmış" adlı oyunu, kültürel ve duygusal yoksunluğun yarattığı toplumsal şiddeti tavizsiz biçimde sergileyerek İngiltere\'de tiyatro sansürünün kaldırılmasında rol oynamıştır.'),
  ('İngiliz feminist ve sosyalist oyun yazarı Caryl Churchill\'in tarihten ve sanattan farklı dönemlerde yaşamış başarılı kadınları (Papa Joan, Sabırlı Griselda vb.) bir akşam yemeği masasında buluşturduğu ünlü oyunu hangisidir?', 'Zirvedeki Kadınlar', ['Dokuzuncu Bulut', 'Ciddi Para', 'Bir Sayı'], 'Caryl Churchill\'in "Top Girls" adlı eseri, üst üste binen konuşma tekniğiyle bireyci kariyer başarısının kadın dayanışması ve annelik üzerinden ödettiği bedelleri sorgular.'),
  ('"Şair Evlenmesi" oyununda Şinasi\'nin karakterlere "Müştak Bey, Hikmet Efendi, Ebullaklaka, Batak Ese" gibi isimler vermesinin temel işlevi nedir?', 'Kişilerin mizaçlarını ve toplumsal rollerini adlarıyla yansıtmak', ['Tarihte yaşamış gerçek devlet adamlarını sahneye taşımak', 'Fransız klasisizmindeki soyluluk unvanlarını Türkçeye uyarlamak', 'Seyircinin karakterleri tanımasını zorlaştırarak merak uyandırmak'], 'Şinasi, geleneksel Türk tiyatrosunun da etkisiyle kişilere karakter özelliklerini özetleyen alegorik/sembolik isimler vermiştir.'),
  ('"Şair Evlenmesi" adlı oyunda Müştak Bey\'in aşık olduğu Kumru Hanım yerine nikahlandırılmak istenen ablanın adı nedir?', 'Sakine Hanım', ['Ziba Dudu', 'Habibe Kadın', 'Sıdıka Hanım'], 'Görücü usulü ve rüşvet temalı oyunda, kılavuz Ziba Dudu ve imam Ebullaklaka aracılığıyla Müştak Bey\'e Kumru Hanım yerine çirkin ve yaşlı ablası Sakine Hanım nikahlanmak istenir.'),
  ('Namık Kemal\'in "Vatan yahut Silistre" oyununda erkek kılığına girerek sevdiği adamın peşinden cepheye giden başkahraman kimdir?', 'Zekiye', ['Dilber', 'Mevhibe', 'Şefika'], 'Oyunda İslam Bey\'e aşık olan Zekiye, "Adem" takma adıyla erkek kılığına girerek Silistre Kalesi savunmasına katılır.'),
  ('"Vatan yahut Silistre" oyununda "Kıyamet kopuyor da vatan yine vatan kalıyor!" diyerek sükunet ve görev bilinciyle öne çıkan komutan karakteri kimdir?', 'Sıtkı Bey', ['İslam Bey', 'Abdullah Çavuş', 'Rüstem Bey'], 'Albay Sıtkı Bey, geçmişteki acılarına rağmen vatan görevini her şeyin üstünde tutan disiplinli komutan ve Zekiye\'nin gerçek babasıdır.'),
  ('Namık Kemal\'in tiyatroyu "faydalı bir eğlence" olarak tanımladığı ve tiyatro anlayışını ayrıntılı biçimde açıkladığı ünlü önsöz hangi eserinin başında yer alır?', 'Celaleddin Harzemşah', ['Zavallı Çocuk', 'Akif Bey', 'Gülnihal'], 'Namık Kemal, 15 perdelik "Celaleddin Harzemşah" oyununun "Mukaddime-i Celal" adlı önsözünde romantik tiyatro görüşlerini ve tiyatronun toplumsal işlevini açıklamıştır.'),
  ('Namık Kemal\'in "Zavallı Çocuk" adlı dramında ailesinin zoruyla Paşa ile evlendirilen ve üzüntüsünden verem olarak hayatını kaybeden genç kız karakteri kimdir?', 'Şefika', ['Zekiye', 'İsmet', 'Dilruba'], '"Zavallı Çocuk"ta Ata\'yı seven on dört yaşındaki Şefika, ailesinin borçları yüzünden yaşlı Halil Paşa ile nişanlanınca vereme yakalanır; Ata ise zehir içerek intihar eder.'),
  ('İlk adı "Raz-ı Dil" olan, ancak sansür nedeniyle adı değiştirilen ve zalim sancakbeyi Kaplan Paşa\'nın zulmüne karşı halkın direnişini anlatan Namık Kemal oyunu hangisidir?', 'Gülnihal', ['Akif Bey', 'Kara Bela', 'Zavallı Çocuk'], '"Gülnihal", Rumeli\'de bir sancakbeyi olan Kaplan Paşa\'nın halka yaptığı baskıyı ve dadı Gülnihal\'in fedakarlığını işleyen politik ve romantik bir dramdır.'),
  ('Ahmet Vefik Paşa\'nın Moliere\'in "Hastalık Hastası" (Le Malade Imaginaire) adlı ünlü komedyasından Osmanlı toplumuna uyarladığı eserin adı nedir?', 'Meraki', ['Zor Nikah', 'Tabib-i Aşk', 'Yorgaki Dandini'], 'Ahmet Vefik Paşa, Moliere\'in "Le Malade Imaginaire" (Hastalık Hastası) adlı eserini "Meraki" adıyla yerli hayata adapte etmiştir.'),
  ('Ahmet Vefik Paşa\'nın Moliere\'in "Zoraki Evlenme" (Le Mariage Forcé) adlı komedyasından Osmanlı yaşamına uyarladığı eserin adı nedir?', 'Zor Nikah', ['Zoraki Tabip', 'Dekbazlık', 'Savruk'], 'Ahmet Vefik Paşa, Moliere\'in "Le Mariage Forcé" adlı oyununu "Zor Nikah", "Le Médecin malgré lui" oyununu ise "Zoraki Tabip" adıyla Türkçeye adapte etmiştir.'),
  ('Tanzimat Dönemi\'nde Ahmet Vefik Paşa ve Direktör Ali Bey\'in Batı tiyatrosundan yaptıkları "adaptasyon" (uyarlama) çalışmalarının temel yöntemi aşağıdakilerden hangisidir?', 'Yabancı eserdeki kişi adlarını, mekanları ve gelenekleri Osmanlı toplum yapısına uygun yerli karşılıklarıyla değiştirmek', ['Eserin özgün dilindeki tüm deyim ve atasözlerini hiçbir değişiklik yapmadan kelimesi kelimesine Türkçeye aktarmak', 'Batılı komedyaların olay örgüsünü bozarak bunları acıklı sonla biten manzum trajedilere dönüştürmek', 'Metindeki diyalogları tamamen çıkarıp yalnızca pandomim ve sessiz sahne hareketleriyle oyunu sergilemek'], 'Adaptasyon (uyarlama), yabancı bir eserin yerel kültür, örf, adet ve kişi isimlerine uyarlanarak yerlileştirilmesi yöntemidir.'),
  ('Osmanlı İmparatorluğu\'nda Müslüman Türk halkına Türkçe oyunlar sergileme tekelini (imtiyazını) elde ederek Gedikpaşa Tiyatrosu\'nu yöneten Ermeni asıllı tiyatrocu kimdir?', 'Güllü Agop', ['Mardiros Mınakyan', 'Tomas Fasulyeciyan', 'Naum Efendi'], 'Asıl adı Agop Vartovyan olan Güllü Agop (sonradan Yakup Efendi), Tiyatro-i Osmani\'yi kurarak Gedikpaşa\'da düzenli Türkçe temsiller vermiş ve yerli yazarları teşvik etmiştir.'),
  ('Türk edebiyatında aruz ölçüsüyle yazılan ilk manzum tiyatro eseri "Eşber" ve hece ölçüsüyle yazılan ilk manzum tiyatro eseri "Nesteren" hangi sanatçıya aittir?', 'Abdülhak Hamit Tarhan', ['Muallim Naci', 'Recaizade Mahmut Ekrem', 'Sami Paşazade Sezai'], 'Abdülhak Hamit Tarhan, Corneille\'in etkisiyle hece ölçülü "Nesteren"i ve aruz ölçülü "Eşber"i yazarak manzum dram alanında ilkleri gerçekleştirmiştir.'),
  ('Musahipzade Celal\'in eski İstanbul mahallelerinde kadınların sosyal hayattan koparılmasını, dedikodu ve görücü usulü evlilikleri mizahi dille işlediği oyunu hangisidir?', 'Kafes Arkasında', ['Köprülüler', 'Bir Kavuk Devrildi', 'Türk Kızı'], '1912\'de sahnelenen "Kafes Arkasında", Musahipzade Celal\'in Meşrutiyet sonrası yazdığı ve geleneksel mahalle baskısını eleştiren önemli töre komedyalarından biridir.'),
  ('Musahipzade Celal\'in Osmanlı Devleti\'nde kadılık kurumunun yozlaşmasını, rüşvet çarkını ve miras hilelerini hicvettiği ünlü töre komedyası hangisidir?', 'Aynaroz Kadısı', ['Lale Devri', 'Macun Hokkası', 'Gül ve Gönül'], '"Aynaroz Kadısı", 18. yüzyılda Aynaroz rahipleriyle iş birliği yapan çıkarcı bir kadının çevirdiği miras dolaplarını ve adalet mekanizmasındaki çürümeyi eleştirir.'),
  ('Musahipzade Celal\'in Sultan İbrahim dönemindeki saray entrikalarını, batıl inançları ve akıl hastası taklidi yapan bir karakter etrafında gelişen olayları işlediği komedyası hangisidir?', 'Fermanlı Deli Hazretleri', ['İstanbul Efendisi', 'Mum Söndü', 'Kaşıkçılar'], '"Fermanlı Deli Hazretleri", padişah fermanıyla dokunulmazlık kazanan bir meczup/deli tiplemesi üzerinden dönemin hurafelerini ve çıkar ilişkilerini sergiler.'),
  ('Osmanlı\'da 1914 yılında İstanbul Şehremini Cemil Topuzlu\'nun girişimi ve Fransız tiyatro adamı Andre Antoine\'ın davetiyle kurulan ilk resmi tiyatro okulu ve kurumunun adı nedir?', 'Darülbedayi', ['Mızıka-i Hümayun', 'Encümen-i Daniş', 'Sanayi-i Nefise Mektebi'], '1914\'te "Darülbedayi-i Osmani" (Güzellikler Evi) adıyla kurulan konservatuvar/tiyatro kurumu, daha sonra İstanbul Şehir Tiyatroları adını almıştır.'),
  ('Darülbedayi\'de sahnelenen ilk yerli ve manzum telif oyun olan "Baykuş" aşağıdakilerden hangi şair ve yazar tarafından kaleme alınmıştır?', 'Halit Fahri Ozansoy', ['Yusuf Ziya Ortaç', 'Faruk Nafiz Çamlıbel', 'Orhan Seyfi Orhon'], 'Beş Hececiler\'den Halit Fahri Ozansoy\'un aruz ölçüsüyle yazdığı sembolik-trajik oyun "Baykuş", 1917\'de Muhsin Ertuğrul\'un başrolü ve yönetmenliğiyle Darülbedayi\'de sahnelenmiştir.'),
  ('Muhsin Ertuğrul\'un Türk tiyatro tarihindeki temel misyonu ve katkısı aşağıdakilerden hangisiyle en doğru biçimde özetlenebilir?', 'Tiyatroyu doğaçlama eğlence anlayışından çıkarıp yönetmen merkezli, yazılı metne sadık ve kurumsal bir sanat dalına dönüştürmek', ['Batı klasiklerinin sahnelenmesini yasaklayarak yalnızca geleneksel Karagöz ve orta oyunu metinlerini sahneye koymak', 'Türk tiyatrosunda ilk epik ve kabare tiyatrosu metinlerini bizzat kaleme alarak oyun yazarlığı alanında çığır açmak', 'Tiyatro binalarını kapatarak tüm gösterilerin yalnızca radyo tiyatrosu formatında yayınlanmasını sağlamak'], 'Muhsin Ertuğrul bir oyun yazarından ziyade kurucu yönetmen, oyuncu ve sanat yöneticisidir; Fransa, Almanya ve Sovyetler Birliği\'ndeki modern sahne disiplinini Türkiye\'de kurumsallaştırmıştır.'),
  ('Haldun Taner\'in "Keşanlı Ali Destanı" adlı oyununda olayların geçtiği gecekondu mahallesinin adı nedir?', 'Sineklidağ', ['Sarıpınar', 'Kuştepe', 'Karagümrük'], 'Oyunda Sineklidağ adlı gecekondu mahallesinde işlemediği bir cinayet (Çamur İhsan\'ı öldürme) yüzünden hapse giren Ali\'nin mahallelinin gözünde bir kahraman ve "efsane" haline getirilmesi anlatılır.'),
  ('"Keşanlı Ali Destanı" adlı oyunda Ali\'nin büyük aşkı olan, kentli zengin ailelerin yanına çalışmaya gidip sosyete özentisiyle değişime uğrayan kadın karakter kimdir?', 'Zilha', ['Nigar', 'Şerife', 'Raziye'], 'Çamur İhsan\'ın yeğeni olan Zilha (Nevvare), Ali ile yaşadığı çatışmalı aşk ve sınıf atlama özentisiyle oyunun en canlı karakterlerinden biridir.'),
  ('Haldun Taner\'in "Keşanlı Ali Destanı"nda Bertolt Brecht\'in epik tiyatro kuramını uygularken yararlandığı yerli kaynaklar aşağıdakilerden hangisidir?', 'Karagöz, orta oyunu ve meddah gibi geleneksel Türk seyirlik oyunlarının açık biçim öğeleri', ['Divan edebiyatındaki kaside ve mesnevilerin aruz vezniyle örülmüş klasik beyit düzeni', 'Tanzimat tiyatrosundaki romantik ölüm sahneleri ve kadercilik anlayışı', 'Servetifünun döneminin salon komedyalarındaki kapalı ve bireysel mekan kurgusu'], 'Haldun Taner, Brecht\'in göstermeci/yabancılaştırmacı epik tiyatrosunu geleneksel Türk tiyatrosunun (orta oyunu, meddah) zaten özünde var olan "açık biçim" (illüzyonu kırma) geleneğiyle sentezlemiştir.'),
  ('Haldun Taner\'in Zeki Alasya, Metin Akpınar ve Ahmet Gülhan ile birlikte 1967 yılında kurduğu, güncel politik ve toplumsal taşlamalarıyla ünlü tiyatro topluluğunun adı nedir?', 'Devekuşu Kabare Tiyatrosu', ['Dostlar Tiyatrosu', 'Kent Oyuncuları', 'Ankara Sanat Tiyatrosu'], 'Haldun Taner, "Bu Şehr-i İstanbul Ki" oyunuyla 1967\'de Türkiye\'nin en uzun soluklu ve etkili kabare topluluğu olan Devekuşu Kabare Tiyatrosu\'nun kurucuları arasında yer almıştır.'),
  ('Haldun Taner\'in geleneksel tiyatronun "Kavuklu" geleneğini ve tuluat tiyatrosunun sinema karşısında gerileyişini buruk bir mizahla işlediği oyunu hangisidir?', 'Ve Değirmen Dönerdi', ['Huzur Çıkmazı', 'Dışardakiler', 'Zilli Zarife'], 'Haldun Taner oyunlarında hem Batılı hem geleneksel motifleri işlemiş; "Ve Değirmen Dönerdi" gibi erken dönem oyunlarında sanat, birey ve değişen toplum değerlerini irdelemiştir.'),
  ('Haldun Taner\'in Bursa\'da Ahmet Vefik Paşa döneminde Moliere\'in bir eserini üç farklı üslupla sahnelemeye çalışan Tomas Fasulyeciyan ve kumpanyasını konu aldığı ödüllü oyunu hangisidir?', 'Sersem Kocanın Kurnaz Karısı', ['Gözlerimi Kaparım Vazifemi Yaparım', 'Zilli Zarife', 'Vatan Kurtaran Şaban'], '"Sersem Kocanın Kurnaz Karısı", oyun içinde oyun kurgusuyla Moliere\'in "George Dandin" eserinin melodram, geleneksel tuluat ve Batılı komedya üsluplarıyla nasıl oynandığını gösteren bir tiyatro klasiğidir.'),
  ('Haldun Taner\'in II. Meşrutiyet\'ten 1960\'lara uzanan yakın Türkiye tarihini "Vicdani" ve "Efruz" adlı iki zıt karakter üzerinden eleştirel bir mizahla anlattığı oyunu hangisidir?', 'Gözlerimi Kaparım Vazifemi Yaparım', ['Fazilet Eczanesi', 'Huzur Çıkmazı', 'Lütfen Dokunmayın'], '"Gözlerimi Kaparım Vazifemi Yaparım" oyununda kurallara körü körüne bağlı saf vatandaş Vicdani ile her devrin çıkarına uyan fırsatçı Efruz\'un yaşam öyküleri karşılaştırılır.'),
  ('Cevat Fehmi Başkut\'un "Paydos" adlı ünlü oyununda maddi değerlerin yükseldiği bir toplumda idealizmini korumaya çalışan ilkokul öğretmeni başkahramanın adı nedir?', 'Murtaza', ['İlyas', 'Süleyman', 'Hüsnü'], '"Paydos" oyununda idealist ilkokul öğretmeni Murtaza Bey, sonradan görme zenginlerin ve ailesinin baskısıyla öğretmenliği bırakıp bakkal dükkanı açmak zorunda kalır ancak manevi değerlerinden kopamaz.'),
  ('Cevat Fehmi Başkut\'un Anadolu\'daki küçük bir kasabada dürüst kalmaya çalışan insanların yerel çıkar grupları ve dedikodu çarkı karşısındaki mücadelesini anlattığı ödüllü oyunu hangisidir?', 'Küçük Şehir', ['Sana Rey Veriyorum', 'Tablodaki Adam', 'Kleopatra\'nın Mezarı'], '1946\'da sahnelenen "Küçük Şehir", büyük kentin yozlaşmış değerlerinin taşraya sızmasını ve kasaba insanının direnişini konu alan başarılı bir Cevat Fehmi Başkut yapıtıdır.'),
  ('Cevat Fehmi Başkut\'un yoğun kar yağışı nedeniyle yolları kapanan bir Anadolu kasabasına gelen ve kaymakam sanılan bir akıl hastasının kasabadaki vurguncularla mücadelesini anlattığı ünlü oyunu hangisidir?', 'Buzlar Çözülmeden', ['Koca Bebek', 'Harput\'ta Bir Amerikalı', 'Soygun'], '"Buzlar Çözülmeden", sinemaya da "Deli Deli Olma / Korkusuz Korkak / Buzlar Çözülmeden" uyarlamalarıyla ilham veren, akıl hastalarının çıkarcı kasaba eşrafından çok daha adil ve akılcı davrandığını gösteren güçlü bir taşlamadır.'),
  ('Cumhuriyet\'in ilk yıllarında "Sönen Kandiller", "Taş Parçası" ve romanından uyarladığı "Yaprak Dökümü" gibi oyunlarıyla tiyatroya da önemli eserler kazandıran yazar kimdir?', 'Reşat Nuri Güntekin', ['Yakup Kadri Karaosmanoğlu', 'Peyami Safa', 'Memduh Şevket Esendal'], 'Tiyatro eleştirileri de yazan Reşat Nuri Güntekin; Hançer, Eski Rüya, Taş Parçası, Hülleci, Balıkesir Muhasebecisi ve Tanrıdağı Ziyafeti gibi pek çok oyun kaleme almıştır.'),
  ('Cumhuriyet Dönemi\'nde "Tohum", "Bir Adam Yaratmak" ve "Reis Bey" adlı felsefi-psikolojik tiyatro eserlerini kaleme alan şair ve yazar kimdir?', 'Necip Fazıl Kısakürek', ['Ahmet Muhip Dıranas', 'Cahit Sıtkı Tarancı', 'Faruk Nafiz Çamlıbel'], 'Necip Fazıl Kısakürek; kader, yaratıcılık sancısı, ölüm korkusu, merhamet ve vicdan temalarını işleyen "Bir Adam Yaratmak", "Reis Bey", "Künye", "Para" ve "Nam-ı Diğer Parmaksız Salih" gibi güçlü dramlar yazmıştır.'),
  ('Faruk Nafiz Çamlıbel\'in Cumhuriyet\'in onuncu yılı dolayısıyla yazdığı; "Akın", "Özyurt" ve "Kahraman" adlı eserlerinde öne çıkan ortak tema aşağıdakilerden hangisidir?', 'Türk tarihinin köklerine yöneliş, yurt sevgisi ve Cumhuriyet devrimlerinin ülküsü', ['Bireyin modern apartman hayatındaki yalnızlığı ve iletişimsizlik bunalımı', 'Osmanlı lonca teşkilatındaki çırak-kalfa ilişkilerinin mizahi eleştirisi', 'Avrupa başkentlerinde eğitim gören gençlerin yaşadığı bohem aşk maceraları'], 'Faruk Nafiz Çamlıbel, 1930\'lu yıllardaki tarih tezine ve inkılap heyecanına paralel olarak Orta Asya\'dan göçü ("Akın", "Özyurt") ve Kurtuluş Savaşı\'nı ("Kahraman") manzum/destansı oyunlarla işlemiştir.'),
  ('Geleneksel köy seyirlik oyunları ve aşık edebiyatı üzerine araştırmalar yapan, "Köşebaşı" ve "Koçyiğit Köroğlu" adlı tiyatro eserleriyle tanınan Cumhuriyet Dönemi şair ve yazarı kimdir?', 'Ahmet Kutsi Tecer', ['Kemalettin Kamu', 'Ömer Bedrettin Uşaklı', 'Zeki Ömer Defne'], 'Ahmet Kutsi Tecer, "Köşebaşı" oyununda İstanbul\'un kenar bir mahallesindeki yirmi dört saatlik yaşamı orta oyunu estetiğiyle birleştirerek çağdaş bir yerli tiyatro dili kurmuştur.'),
  ('Ahmet Muhip Dıranas\'ın kaleme aldığı ve aile içi gizli bir aşk ile kuşaklar arası çatışmayı psikolojik derinlikle işleyen ünlü tiyatro eseri hangisidir?', 'Gölgeler', ['Kafatası', 'Süt Kardeşler', 'Cengiz Han\'ın Bisikleti'], 'Şiirleriyle tanınan Ahmet Muhip Dıranas, "Gölgeler" ve "O Böyle İstemezdi" adlı oyunlarıyla Cumhuriyet Dönemi\'nde şiirsel ve psikolojik tiyatronun seçkin örneklerini vermiştir.'),
  ('Tanzimat\'ın birinci döneminde tiyatro türünün gazete ile birlikte edebiyatçıların en çok önem verdiği türlerden biri olmasının temel toplumsal nedeni nedir?', 'Okuma yazma oranının düşük olduğu bir toplumda halka doğrudan ve görsel-işitsel yolla ulaşarak fikirleri yayma imkanı sunması', ['Saray yönetiminin yalnızca tiyatro yazarlarına yüksek maaş ve vergi muafiyeti bağlamış olması', 'Matbaa makinelerinin roman ve şiir basımı için teknik olarak yetersiz kalması', 'Halkın geleneksel Karagöz ve meddah gösterilerini daha önce hiç izlememiş olması'], 'Tanzimat aydınları (özellikle Namık Kemal ve Ahmet Mithat), okuryazarlığın az olduğu Osmanlı toplumunda tiyatroyu halkı aydınlatmanın ve vatan-hürriyet-aile fikirlerini aktarmanın en etkili okulu olarak görmüştür.'),
  ('Servetifünun Dönemi\'nde şair kimliğinin yanı sıra "Yalan" ve "Körebe" adlı iki tiyatro oyunu da kaleme alan sanatçı kimdir?', 'Cenap Şahabettin', ['Hüseyin Suat Yalçın', 'Mehmet Rauf', 'Süleyman Nazif'], 'Cenap Şahabettin, II. Meşrutiyet\'in ilanından sonra "Körebe" adlı tek perdelik komedyası ile "Yalan" adlı dört perdelik dramını yazmıştır.'),
  ('Servetifünun edebiyatının usta romancısı olmasına rağmen tiyatro türünde de "Kabus", "Füruzan" ve "Fare" adlı üç eser kaleme alan yazar aşağıdakilerden hangisidir?', 'Halit Ziya Uşaklıgil', ['Mehmet Rauf', 'Hüseyin Cahit Yalçın', 'Tevfik Fikret'], 'Halit Ziya Uşaklıgil; telif dramı "Kabus" ile Fransızcadan uyarladığı "Füruzan" ve "Fare" adlı oyunlarıyla Servetifünun tiyatrosuna katkıda bulunmuştur.'),
  ('Turgut Özakman\'ın II. Abdülhamit dönemindeki istibdat ortamında bir kabadayının (Rasim Baba ve oğlu Yusuf) saray paşasının konağı etrafında gelişen öyküsünü mizahi dille anlattığı ünlü oyunu hangisidir?', 'Fehim Paşa Konağı', ['Resimli Osmanlı Tarihi', 'Sarıpınar 1914', 'Bir Şehnaz Oyun'], '1979\'da yazılan "Fehim Paşa Konağı", gölge oyunu (Karagöz) sanatçısı Yusuf ile Fehim Paşa\'nın kızı Mihriban\'ın aşkı üzerinden korku ve baskı iktidarını ustalıkla hicveder.'),
  ('Turgut Özakman\'ın üç farklı kuşaktan bireylerin (dede, baba-anne ve torun) aynı çatı altında yaşadığı çatışmaları sıcak ve gerçekçi bir dille anlattığı oyunu hangisidir?', 'Ocak', ['Pembe Evin Kaderi', 'Güneşte On Kişi', 'Duvarların Ötesi'], '"Ocak" oyununda ekonomik sıkıntılar içindeki orta halli bir Türk ailesinin kuşaklar arası hayalleri, çatışmaları ve birbirine tutunarak ayakta kalma çabası işlenir.'),
  ('Turgut Özakman\'ın gençlerin aileleri, okul düzeni ve toplumla yaşadıkları iletişim sorunlarını müzikli ve dinamik skeçler halinde sunduğu popüler oyunu hangisidir?', 'Ah Şu Gençler', ['Töre', 'Komşularımız', 'Korkma İnsancık Korkma'], 'Liselerde ve amatör topluluklarda en çok sahnelenen oyunlardan biri olan "Ah Şu Gençler", gençlik sorunlarına hem ebeveynlerin hem gençlerin gözünden esprili bir ayna tutar.'),
  ('Turgut Özakman\'ın kan davası ve namus töresi yüzünden ölümle burun buruna gelen insanların dramını yaşlı "Nene" karakterinin barışçıl direnişiyle işlediği oyunu hangisidir?', 'Töre', ['Güneşte On Kişi', 'Kanaviçe', 'ocak'], '"Töre", Doğu Anadolu\'da kuşaklar boyu süren kan davası geleneğine kadınların ve yaşam sevgisinin başkaldırısını konu alan sarsıcı bir oyundur.'),
  ('Güngör Dilmen\'in Frigya Kralı Midas\'ı konu aldığı ünlü "Midas Üçlemesi"ni oluşturan oyunlar aşağıdakilerin hangisinde bir arada doğru verilmiştir?', 'Midas\'ın Kulakları - Midas\'ın Altınları - Midas\'ın Kör Düğümü', ['Midas\'ın Kulakları - Canlı Maymun Lokantası - Kurban', 'Midas\'ın Altınları - Deli Dumrul - Ak Tanrılar', 'Midas\'ın Kör Düğümü - Bağdat Hatun - Ben Anadolu'], 'Güngör Dilmen, Apollon ile Pan arasındaki yarışmada hakemlik yapan Frigya Kralı Midas efsanesini "Midas\'ın Kulakları", "Midas\'ın Altınları" ve "Midas\'ın Kör Düğümü" adlı üçlemede işlemiştir.'),
  ('Güngör Dilmen\'in "Midas\'ın Kulakları" adlı tek perdelik manzum-şiirsel oyununda Kral Midas\'ın eşek kulaklarına sahip olduğu sırrını saklayamayıp kuyuya haykıran karakter kimdir?', 'Berber', ['Kahin', 'Çoban', 'Muhafız'], 'Apollon\'un cezalandırdığı Kral Midas\'ın kulaklarını yalnızca Berberi görür; sırrın ağırlığına dayanamayan Berber bunu bir kuyuya fısıldar, kuyudaki sazlar ise sırrı rüzgarla tüm ülkeye yayar.'),
  ('Güngör Dilmen\'in Hong Kong\'da balayına çıkan Amerikalı petrol kralı Jonathan çifti ile Çinli şair Wong arasındaki karşılaşma üzerinden Batı\'nın sömürgeci vahşetini eleştirdiği absürt-eleştirel oyunu hangisidir?', 'Canlı Maymun Lokantası', ['Ak Tanrılar', 'Küp Hamit', 'Aşkımız Aksaray\'ın En Büyük Yangını'], '1960\'larde büyük yankı uyandıran "Canlı Maymun Lokantası", kapitalist tüketim toplumunun doğulu/yoksul insanı ve sanatı nasıl acımasızca tükettiğini çarpıcı bir metaforla sergiler.'),
  ('Orhan Asena\'nın Sümer destanından esinlenerek yazdığı, ölümsüzlük arayışı içindeki Uruk Kralı\'nın tanrılara başkaldırısını ve insanlaşma bilincini işlediği ilk ve en ünlü oyunu hangisidir?', 'Tanrılar ve İnsanlar', ['Tohum ve Toprak', 'Fadik Kız', 'Simavnalı Şeyh Bedreddin'], 'İlk olarak "Korku" ve ardından "Tanrılar ve İnsanlar (Gılgamış)" adıyla bilinen bu eser, Orhan Asena\'nın 1954\'te Devlet Tiyatroları\'nda sahnelenen başyapıtıdır.'),
  ('Orhan Asena\'nın Kanuni Sultan Süleyman dönemindeki saray entrikalarını, Şehzade Mustafa ve Şehzade Bayezid\'in trajik sonlarını kapsayan "Kanuni Üçlemesi" içinde yer alan ünlü oyunu hangisidir?', 'Hürrem Sultan', ['Kösem Sultan', 'IV. Murat', 'Deli İbrahim'], 'Orhan Asena\'nın iktidar ve annelik/tutku çatışmasını işlediği "Hürrem Sultan", yazarın "İlk Yıllar - Roksolan", "Hürrem Sultan", "Ya Devlet Başa Ya Kuzgun Leşe" (ve "Sığıntı") dizisinin en tanınmış halkasıdır.'),
  ('Orhan Asena\'nın Aydın ve çevresinde ağaların zulmüne başkaldırarak dağa çıkan ve kısa süreliğine yönetimi ele geçiren bir efenin yaşamını konu aldığı ödüllü oyunu hangisidir?', 'Atçalı Kel Mehmet', ['Alemdar Paşa', 'Seyitgazi', 'Toroslardan Öteye'], '1970\'te TRT Sanat Ödülleri\'nde başarı kazanan "Atçalı Kel Mehmet", yoksul bir ırgatken "Vali-i Vilayet Hademe-i Devlet Atçalı Kel Mehmet" mührü kazıtan halk kahramanının trajedisini anlatır.'),
  ('Turan Oflazoğlu\'nun Osmanlı İmparatorluğu\'nda 17. yüzyıldaki iktidar bunalımını birbirini tamamlayan bir "İktidar Üçlemesi" olarak kurguladığı oyunlar hangileridir?', 'Kösem Sultan - Deli İbrahim - IV. Murat', ['Hürrem Sultan - Genç Osman - Cem Sultan', 'Keziban - Allah\'ın Dediği Olur - Elif Ana', 'Sokrates Savunuyor - Sinan - Yavuz Selim'], 'Turan Oflazoğlu; "Deli İbrahim", "IV. Murat" ve "Kösem Sultan" oyunlarıyla 17. yüzyıl Osmanlı sarayındaki mutlak iktidar, korku ve kişilik bölünmelerini anıtsal bir üçlemeye dönüştürmüştür.'),
  ('Turan Oflazoğlu\'nun kan davası geleneğini ve töre baskısını köy ortamında "Keziban" adlı genç bir kadının trajedisi üzerinden işlediği ilk dönem oyunu hangisidir?', 'Keziban', ['Fadik Kız', 'Susuz Yaz', 'Nalınlar'], 'Oflazoğlu\'nun ABD\'de tiyatro eğitimi aldığı yıllarda yazdığı tek perdelik "Keziban" ve köy komedyası "Allah\'ın Dediği Olur", yazarın Anadolu kırsalına yöneldiği önemli eserleridir.'),
  ('Cumhuriyet Dönemi\'nde "Sarı Naciye", "İsyancılar" ve "Yunus Emre" gibi oyunlarıyla köy gerçekliğini, bürokrasiyi ve tasavvuf hoşgörüsünü sahneye taşıyan yazar kimdir?', 'Recep Bilginer', ['Cahit Atay', 'Hidayet Sayın', 'Necati Cumalı'], 'Gazeteci ve oyun yazarı Recep Bilginer; "İsyancılar", "Sarı Naciye", "Ben Devletim", "Parkta Bir Sonbahar Günüydü" ve "Mevlana" gibi toplumsal-tarihsel oyunlarıyla tanınır.'),
  ('Şair ve romancı kimliğinin yanı sıra "Boş Beşik", "Nalınlar", "Susuz Yaz" ve "Derya Gülü" gibi lirik ve gerçekçi tiyatro eserleri de yazan sanatçı kimdir?', 'Necati Cumalı', ['Fakir Baykurt', 'Talip Apaydın', 'Samim Kocagöz'], 'Necati Cumalı, hem Ege kırsalındaki töre ve toprak/su çatışmalarını ("Boş Beşik", "Nalınlar", "Susuz Yaz") hem de kıyı insanlarının yalnızlığını ("Derya Gülü") güçlü oyunlara dönüştürmüştür.'),
  ('Cumhuriyet Dönemi\'nde "Pusuda", "Karaların Memetleri" ve "Sultan Gelin" adlı oyunlarıyla köy ve kasaba insanının ağalık düzeni ve töre karşısındaki trajikomik durumunu anlatan yazar kimdir?', 'Cahit Atay', ['Refik Erduran', 'Başar Sabuncu', 'Vasıf Öngören'], '"Köy tiyatrosu" akımının en önemli isimlerinden Cahit Atay, özellikle "Pusuda" adlı tek perdelik oyunuyla ağa-aydın-köylü üçgenindeki yabancılaşmayı çarpıcı biçimde işlemiştir.'),
  ('Cumhuriyet Dönemi tiyatrosunda "Cengiz Han\'ın Bisikleti" ve "Bir Kilo Namus" adlı toplumsal hiciv komedyalarıyla tanınan yazar aşağıdakilerden hangisidir?', 'Refik Erduran', ['Aziz Nesin', 'Çetin Altan', 'Muzaffer İzgü'], 'Refik Erduran; çok eşlilikten kurtulup modern hayata uyum sağlamaya çalışan eski bir Osmanlı erkeğini anlattığı "Cengiz Han\'ın Bisikleti" başta olmak üzere hızlı tempolu güldürüleriyle ünlüdür.'),
  ('Bertolt Brecht\'in epik tiyatro anlayışını sınıf bilinciyle birleştiren, "Asiye Nasıl Kurtulur?" ve "Zengin Mutfağı" adlı oyunların yazarı kimdir?', 'Vasıf Öngören', ['Sermet Çağan', 'Oktay Arayıcı', 'Haşmet Zeybek'], 'Ankara Birliği Sahnesi\'nin kurucularından Vasıf Öngören; "Göç", "Asiye Nasıl Kurtulur?", "Oyun Nasıl Oynanmalı?" ve "Zengin Mutfağı" ile toplumcu gerçekçi epik tiyatronun ustası olmuştur.'),
  ('Mizah öykülerinin yanı sıra "Toros Canavarı", "Yaşar Ne Yaşar Ne Yaşamaz" ve soyut-felsefi nitelikli "Çiçu" gibi önemli tiyatro oyunları da kaleme alan usta yazar kimdir?', 'Aziz Nesin', ['Rıfat Ilgaz', 'Haldun Taner', 'Muzaffer İzgü'], 'Aziz Nesin; Biraz Gelir misiniz, Çiçu, Bişey Yap Met gibi evrensel-soyut oyunların yanında Toros Canavarı ve Yaşar Ne Yaşar Ne Yaşamaz gibi keskin toplumsal taşlamalar yazmıştır.'),
  ('Geleneksel orta oyunu geleneğini modern tiyatroyla birleştirerek "Ortaoyuncular" topluluğunu kuran, "Ferhangi Şeyler" ve "Şahları da Vururlar" adlı oyunların yazarı ve oyuncusu kimdir?', 'Ferhan Şensoy', ['Haldun Dormen', 'Genco Erkal', 'Müjdat Gezen'], 'Münir Özkul\'dan Dümbüllü\'nün kavuğunu devralan Ferhan Şensoy; Ses Tiyatrosu\'nda sahnelediği müzikli, taşlamalı ve kıvrak dilli oyunlarıyla özgün bir üslup yaratmıştır.'),
  ('Kadınların toplumdaki ikincil konumunu, evlilik kurumunu ve aydın yabancılaşmasını gerçekçi-psikolojik bir dille işleyen; "Çatıdaki Çatlak", "Kördüğüm" ve "Tıpkı Sen Tıpkı Ben" oyunlarının kadın yazarı kimdir?', 'Adalet Ağaoğlu', ['Sevim Burak', 'Nezihe Meriç', 'Bilge Karasu'], 'Romancılığından önce TRT\'de dramaturgluk yapan ve oyun yazarlığıyla ünlenen Adalet Ağaoğlu; Evcilik Oyunu, Çatıdaki Çatlak, Tombala ve Kozalar gibi yenilikçi oyunlar yazmıştır.'),
  ('Şair ve öykücü kimliğinin yanında "Evin Üstündeki Bulut", "Şakacı", "Kahvede Şenlik Var" ve "Kral Üşümesi" adlı şiirsel-ironik tiyatro eserlerini kaleme alan sanatçı kimdir?', 'Sabahattin Kudret Aksal', ['Oktay Rifat', 'Melih Cevdet Anday', 'Behçet Necatigil'], 'Sabahattin Kudret Aksal, küçük burjuva ailesini ve evlilik kurumunu ince bir ironiyle sorguladığı "Kahvede Şenlik Var" ve iktidar olgusunu tartıştığı "Kral Üşümesi" ile tiyatromuza önemli eserler kazandırmıştır.'),
  ('Cumhuriyet Dönemi\'nde 19. yüzyıl sonu İstanbul yaşamını müzikli komedya (vodvil/müzikal) biçiminde canlandıran "Yedi Kocalı Hürmüz" adlı ünlü eserin yazarı kimdir?', 'Sadık Şendil', ['Sulhi Dölek', 'Suavi Süalp', 'Muammer Karaca'], 'Sadık Şendil\'in geleneksel halk hikayeleri ve orta oyunu motiflerinden yararlanarak yazdığı "Yedi Kocalı Hürmüz" ve "Kanlı Nigar", Türk tiyatrosunun en sevilen müzikli güldürülerindendir.'),
  ('Geleneksel meddah ve orta oyunu kurgusunu toplumcu bir bakışla yenileyen; "Rumuz Goncagül", "Seferi Ramazan Bey\'in Nafile Dünyası" ve "Bir Ölümün Toplumsal Anatomisi" oyunlarının yazarı kimdir?', 'Oktay Arayıcı', ['Tuncer Cücenoğlu', 'Başar Sabuncu', 'Memet Baydur'], 'Erken yaşta hayatını kaybeden Oktay Arayıcı, özellikle gazete ilanıyla evlenmeye çalışan dar gelirli anne-kızın öyküsünü anlattığı "Rumuz Goncagül" (müzikleri Timur Selçuk) ile klasikleşmiştir.'),
  ('Yurt dışında en çok sahnelenen çağdaş Türk oyun yazarlarından biri olan; "Çıkmaz Sokak", "Kadıncıklar" ve bir çığ korkusu üzerinden baskı rejimlerini anlattığı "Çığ" adlı eserin yazarı kimdir?', 'Tuncer Cücenoğlu', ['Ülker Köksal', 'Turgut Özakman', 'Hidayet Sayın'], 'Tuncer Cücenoğlu\'nun çığ düşmesin diye insanların dokuz ay boyunca fısıltıyla konuşmaya zorlandığı bir dağı konu alan alegorik oyunu "Çığ", onlarca yabancı dile çevrilerek sahnelenmiştir.'),
  ('1936 yılında Ankara Devlet Konservatuvarı\'nın kurulması ve tiyatro-opera bölümlerinin yapılandırılması sürecinde Türkiye\'ye davet edilerek görev yapan ünlü Alman tiyatro ve opera yönetmeni kimdir?', 'Carl Ebert', ['Andre Antoine', 'Bertolt Brecht', 'Konstantin Stanislavski'], 'Nazi Almanyası\'ndan ayrılarak Atatürk dönemi kültür hamlesi kapsamında Türkiye\'ye gelen Carl Ebert, dokuz yıl boyunca Devlet Konservatuvarı Tatbikat Sahnesi\'nde çağdaş Türk tiyatrocularının yetişmesini sağlamıştır.'),
  ('Batılı anlamda tiyatrodan önce Osmanlı toplumunda varlığını sürdüren geleneksel Türk tiyatrosu (Karagöz, orta oyunu, meddah) ile Tanzimat sonrası modern tiyatro arasındaki en temel fark nedir?', 'Geleneksel tiyatronun doğaçlamaya (tuluata) ve belirli tiplere, modern tiyatronun ise yazılı metne ve çok boyutlu karakterlere dayanması', ['Geleneksel tiyatronun yalnızca saray salonlarında, modern tiyatronun ise yalnızca köy meydanlarında sergilenmesi', 'Geleneksel tiyatroda güldürü öğesinin hiç bulunmaması, modern tiyatronun ise yalnızca komedyalardan oluşması', 'Geleneksel tiyatronun aruz ölçülü manzum metinlere, modern tiyatronun ise yalnızca tek kişilik masallara dayanması'], 'Geleneksel Türk tiyatrosu sahnesiz, dekorsuz ve yazılı metinsiz (usta-çırak ve doğaçlama) bir göstermeci geleneğe dayanırken; modern tiyatro yazılı metin, sahne, dekor ve karakter derinliği getirmiştir.'),
  ('Tiyatro kurumlarında sahnelenecek oyun metinlerini seçen, inceleyen, gerektiğinde sahnelemeye uygun biçimde düzenleyen ve kuramsal danışmanlık yapan uzmana ne ad verilir?', 'Dramaturg', ['Mübayaa memuru', 'Kondüvit', 'Aksesuarcı'], 'Turgut Özakman ve Adalet Ağaoğlu gibi pek çok yazarımızın da üstlendiği "dramaturg"luk görevi, tiyatronun edebi ve düşünsel mutfağını yönetir.'),
  ('Bir tiyatro eserini sahneye koyan, oyuncuların yorumlarını ve sahne trafiğini estetik bir bütünlük içinde yöneten sanatçıya tiyatro dilinde hangi ad verilir?', 'Rejisör', ['Suflör', 'Figüran', 'Dublör'], 'Fransızca kökenli "rejisör" (yönetmen) terimi, Türk tiyatrosunda özellikle Muhsin Ertuğrul ile birlikte kurumsal bir kimlik kazanmıştır.'),
  ('Abdülhak Hamit Tarhan\'ın İslam ordularının İspanya\'yı fethini ve komutanın gemileri yaktırmasını işlediği ünlü tarihsel tiyatro eseri hangisidir?', 'Tarık yahut Endülüs Fethi', ['Sardanapal', 'Liberte', 'Zeynep'], '"Tarık yahut Endülüs Fethi", Abdülhak Hamit Tarhan\'ın İslam tarihinden aldığı kahramanlık ve adalet temalarını işlediği en tanınmış okuma tiyatrolarından biridir.'),
  ('Tanzimat Dönemi\'nde "Eyvah", "Açık Baş" ve "Çerkez Özdenleri" gibi oyunlar yazarak tiyatroyu halkı eğitme aracı olarak kullanan "Yazı Makinesi" lakaplı yazar kimdir?', 'Ahmet Mithat Efendi', ['Şemsettin Sami', 'Muallim Naci', 'Nabizade Nazım'], 'Ahmet Mithat Efendi; çok eşliliğin sakıncalarını anlattığı "Eyvah", dini istismarı eleştirdiği "Açık Baş" ve "Ahz-ı Sar" gibi oyunlarıyla tiyatroda da üretken bir isim olmuştur.'),
  ('Ekrem Reşit Rey\'in librettosunu yazdığı, Cemal Reşit Rey\'in bestelediği ve Cumhuriyet\'in ilk yıllarında Batılılaşma özentisi içindeki sosyeteyle iki kenar mahalle hırsızının karşılaşmasını anlatan ünlü operet hangisidir?', 'Lüküs Hayat', ['Deli Dolu', 'Saz Caz', 'Hava Cıva'], '1933 yılında İstanbul Şehir Tiyatroları\'nda ilk kez sahnelenen "Lüküs Hayat", Rıza ile Fıstık karakterleri üzerinden alafranga özentisini hicveden ölümsüz bir müzikal klasiğidir.'),
  ('Yıldız Kenter ve Müşfik Kenter kardeşlerin Muhsin Ertuğrul\'un desteğiyle kurdukları, Türk ve dünya tiyatrosunun seçkin eserlerini onlarca yıl sahneleyen özel tiyatro topluluğunun adı nedir?', 'Kent Oyuncuları', ['Ankara Sanat Tiyatrosu', 'Tiyatro Kare', 'Oyun Atölyesi'], 'Başlangıçta "Site Tiyatrosu" adıyla yola çıkan ve ardından "Kent Oyuncuları" adını alan topluluk, Kenter Tiyatrosu binasında çağdaş oyunculuk üslubunun simgesi olmuştur.'),
  ('Genco Erkal tarafından 1969 yılında kurulan, Nazım Hikmet uyarlamaları ve "Bir Delinin Hatıra Defteri" gibi politik-toplumcu oyunlarla özdeşleşen tiyatro topluluğu hangisidir?', 'Dostlar Tiyatrosu', ['Devekuşu Kabare', 'Dormen Tiyatrosu', 'Kenter Tiyatrosu'], 'Genco Erkal\'ın öncülüğündeki Dostlar Tiyatrosu; belgesel tiyatro, epik tiyatro ve edebiyat uyarlamalarıyla toplumcu Türk tiyatrosunun en önemli odaklarından biri olmuştur.'),
  ('Bir lise tiyatro kulübü, sahnede dekor ve yanılsama kullanmak yerine anlatıcıların doğrudan seyirciye hitap ettiği, şarkı ve projeksiyon yazılarıyla seyirciyi eleştirel düşünmeye çağıran yerli bir klasik sahnelemek isterse aşağıdaki oyunlardan hangisini seçmelidir?', 'Keşanlı Ali Destanı', ['Zavallı Çocuk', 'Bir Adam Yaratmak', 'Gölgeler'], 'Haldun Taner\'in "Keşanlı Ali Destanı" epik (göstermeci) tiyatronun ilk yerli klasiğidir; diğer seçeneklerdeki oyunlar ise kapalı biçim (dramatik/yanılsamacı) kurguya sahiptir.'),
  ('Osmanlı İmparatorluğu\'nda 17. yüzyıldaki mutlak iktidar kavgalarını ve padişahların ruhsal bunalımlarını Shakespeare trajedilerine yakın şiirsel bir dille incelemek isteyen bir araştırmacı öncelikle hangi iki yazarımızın oyunlarına başvurmalıdır?', 'Orhan Asena ve Turan Oflazoğlu', ['İbrahim Şinasi ve Direktör Ali Bey', 'Cevat Fehmi Başkut ve Sadık Şendil', 'İbnürrefik Ahmet Nuri ve Haldun Dormen'], 'Orhan Asena ve Turan Oflazoğlu, Osmanlı tarihindeki iktidar trajedisini klasik-şiirsel trajedi boyutuyla işleyen en yetkin iki Cumhuriyet Dönemi oyun yazarımızdır.'),
  ('Cumhuriyet Dönemi\'nde Hidayet Sayın\'ın kaleme aldığı ve köy yaşamındaki ağalık baskısını, batıl inançları ve töre çıkmazını işleyen ünlü oyunları aşağıdakilerden hangisidir?', 'Topuzlu ve Pembe Kadın', ['Paydos ve Küçük Şehir', 'Kافes Arkasında ve Aynaroz Kadısı', 'Fazilet Eczanesi ve Günün Adamı'], 'Doktor ve oyun yazarı Hidayet Sayın, Yıldız Kenter\'in de uzun yıllar başrolünü oynadığı "Pembe Kadın" ve köydeki zorbalığı anlatan "Topuzlu", "Kör Döğüşü" gibi oyunlarıyla tanınır.'),
  ('Haldun Taner\'in geleneksel değerlerle modern yaşam arasında sıkışan yaşlı bir ressamın ve ailesinin değişen toplum karşısındaki durumunu işlediği ilk dönem oyunu hangisidir?', 'Ve Değirmen Dönerdi', ['Huzur Çıkmazı', 'Dışardakiler', 'Zilli Zarife'], 'Haldun Taner oyunlarında hem Batılı hem geleneksel motifleri işlemiş; "Ve Değirmen Dönerdi" gibi erken dönem oyunlarında sanat, birey ve değişen toplum değerlerini irdelemiştir.'),
  ('Orhan Asena\'nın Kanuni Sultan Süleyman dönemindeki saray entrikalarını ve şehzadelerin trajik sonlarını kapsayan "Kanuni Dörtlemesi" içinde yer alan en ünlü oyunu hangisidir?', 'Hürrem Sultan', ['Kösem Sultan', 'IV. Murat', 'Deli İbrahim'], 'Orhan Asena\'nın iktidar ve annelik/tutku çatışmasını işlediği "Hürrem Sultan", yazarın "İlk Yıllar - Roksolan", "Hürrem Sultan", "Ya Devlet Başa Ya Kuzgun Leşe" ve "Sığıntı" dizisinin en tanınmış halkasıdır.'),
  ('Kadınların toplumdaki ikincil konumunu, evlilik kurumunu ve aydın yabancılaşmasını gerçekçi-psikolojik bir dille işleyen; "Çatıdaki Çatlak", "Kozalar" ve "Evcilik Oyunu" adlı eserlerin yazarı kimdir?', 'Adalet Ağaoğlu', ['Sevim Burak', 'Nezihe Meriç', 'Bilge Karasu'], 'Romancılığından önce TRT\'de dramaturgluk yapan ve oyun yazarlığıyla ünlenen Adalet Ağaoğlu; Evcilik Oyunu, Çatıdaki Çatlak, Tombala ve Kozalar gibi yenilikçi oyunlar yazmıştır.'),
  ('Geleneksel Türk tiyatrosu türleri, Karagöz, orta oyunu ve Anadolu seyirlik köylü oyunları üzerine uluslararası düzeyde temel başvuru kitaplarını yazan tiyatro tarihçisi ve araştırmacımız kimdir?', 'Metin And', ['Sabahattin Kudret Aksal', 'Refik Erduran', 'Recep Bilginer'], 'Prof. Dr. Metin And; "Geleneksel Türk Tiyatrosu", "Tanzimat ve İstibdat Döneminde Türk Tiyatrosu" ve "Cumhuriyet Dönemi Türk Tiyatrosu" gibi anıtsal incelemeleriyle tiyatro biliminin Türkiye\'deki öncüsüdür.'),
  ('Abdülhak Hamit Tarhan\'ın Londra sosyetesindeki ahlaki çöküntüyü, Lady Dick ve Hintli uşağı Davalaciro etrafında gelişen vahşi ihtirasları manzum-mensur karışık işlediği ünlü dramı hangisidir?', 'Finten', ['Duhter-i Hindu', 'Tarık yahut Endülüs Fethi', 'Nesteren'], 'Shakespeare\'in "Macbeth" ve "Othello" eserlerinden izler taşıyan "Finten", Kanadalı hırslı bir kadın olan Finten (Lady Dick) ile uşağı Davalaciro\'nun tutku ve cinayet dolu öyküsünü anlatır.'),
  ('Turgut Özakman\'ın I. Dünya Savaşı arifesinde İstanbul\'daki bir randevuevinde çalışan Şehnaz ile mahallenin bıçkın delikanlısı Müştak\'ın aşkını geleneksel tiyatro öğeleriyle anlattığı müzikli oyunu hangisidir?', 'Bir Şehnaz Oyun', ['Resimli Osmanlı Tarihi', 'Pembe Evin Kaderi', 'Duvarların Ötesi'], '"Bir Şehnaz Oyun", müzikli-göstermeci kurgusuyla hem işgal ve savaş öncesi İstanbul atmosferini hem de toplumsal ikiyüzlülüğü neşeli ve buruk bir dille sahneye taşır.'),
  ('Orhan Asena\'nın 1973 yılında Şili\'de seçilmiş devlet başkanı Salvador Allende\'nin askeri darbeyle devrilmesi sonrasında yaşanan insan hakları ihlallerini mahkeme kurgusuyla işlediği politik oyunu hangisidir?', 'Şili\'de Av', ['Tanrılar ve İnsanlar', 'Hürrem Sultan', 'Atçalı Kel Mehmet'], '"Şili\'de Av", Orhan Asena\'nın evrensel insan hakları, diktatörlük ve işkence sorunlarına yöneldiği belgesel-politik nitelikli güçlü bir tiyatro eseridir.'),
  ('Ahmet Vefik Paşa\'nın "Zor Nikah" ve "Meraki" uyarlamalarının Tanzimat seyircisi tarafından yabancı eser gibi değil de yerli birer oyun gibi benimsenmesinin temel nedeni aşağıdakilerden hangisidir?', 'Paşa\'nın Moliere metinlerini Osmanlı örf, adet, deyim ve mahalle tipleriyle ustaca yoğurarak kültürel dokuya uyarlaması', ['Oyunların tamamının Fransızca oynanmasına rağmen sahne kenarında Türkçe özetlerinin dağıtılması', 'Metinlerdeki komik unsurların çıkarılıp yerine yalnızca ağır divan şiiri gazellerinin eklenmesi', 'Eserlerin yalnızca saray içindeki yabancı elçilik görevlilerine kapalı gişe olarak sergilenmesi'], 'Ahmet Vefik Paşa, çeviri yerine başarılı bir yerlileştirme (adaptasyon) uygulayarak Fransız tiplerini Osmanlı toplumundaki canlı karşılıklarına dönüştürmüş ve tiyatro sevgisini yaygınlaştırmıştır.'),
];
